class Common(unittest.TestCase):
    def test_glob(self):
        self.assertTrue(glob_match(".github/workflows/ci.yml", ".github/**"), "a dot-directory is an ordinary path")
        self.assertTrue(glob_match(".env", "**/.env"))
        self.assertTrue(glob_match(".claude/state/x.txt", ".claude/state/**"))
        self.assertTrue(glob_match("./src/a.py", "src/**"), "only a literal ./ prefix is removed")
        self.assertTrue(glob_match("src/a/b.py", "src/**"))
        self.assertTrue(glob_match("x/migrations/1.sql", "**/migrations/**"))
        self.assertTrue(glob_match("a.py", "**/*.py"))
        self.assertTrue(glob_match("deep/a.tsx", "**/*.{jsx,tsx}"))
        self.assertFalse(glob_match("src/a.py", "tests/**"))
        self.assertTrue(glob_match("infra/main.tf", "infra/"))

    def test_frontmatter_subset_parser(self):
        from gates.common import _mini_yaml
        self.assertEqual(_mini_yaml('status: APPROVED   # DRAFT | APPROVED\nq: "a # not a comment"\n'), {"status": "APPROVED", "q": "a # not a comment"})
        with self.assertRaisesRegex(GateFault, "unterminated quote"):
            _mini_yaml('certifies: "broken\n')
        d = _mini_yaml('description: "x"\napplicable_when:\n  phase: [IMPLEMENT, QA]\n  always: true\nlist:\n  - a\n  - b\nn: 3\n')
        self.assertEqual(d["applicable_when"]["phase"], ["IMPLEMENT", "QA"])
        self.assertIs(d["applicable_when"]["always"], True)
        self.assertEqual(d["list"], ["a", "b"])
        self.assertEqual(d["n"], 3)


class Corpus(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.repo = fixture_repo(Path(self.tmp.name))

    def tearDown(self):
        self.tmp.cleanup()

    def test_law_index_parses_both_shapes(self):
        laws = corpus.laws(self.repo)
        u = {l["id"]: l for l in laws["universal"]}
        self.assertEqual(set(u), {"LAW-01", "LAW-02", "LAW-07"})
        self.assertEqual(u["LAW-01"]["body"], ".claude/skills/factory-governance-loading/SKILL.md")
        self.assertEqual(u["LAW-01"]["records"], ["ADR-EVOL-026", "ADR-EVOL-043"])
        self.assertEqual(u["LAW-01"]["sentence"], "Operational law lives in one index and every law has one body.")
        self.assertEqual(u["LAW-07"]["body"], "inline")
        p = {l["id"]: l for l in laws["project"]}
        self.assertEqual(set(p), {"PLAW-01", "PLAW-02"})
        self.assertEqual(p["PLAW-02"]["body"], "rules/stateless.md")

    def test_body_section_resolution(self):
        laws = corpus.laws(self.repo)
        plaw1 = next(l for l in laws["project"] if l["id"] == "PLAW-01")
        f, heading, quoted, body = corpus.body_section(self.repo, plaw1)
        self.assertEqual(f, self.repo / ".claude/rules/architecture.md")
        self.assertEqual(quoted, plaw1["sentence"])
        self.assertIn("body", body)
        plaw2 = next(l for l in laws["project"] if l["id"] == "PLAW-02")
        _, _, quoted2, _ = corpus.body_section(self.repo, plaw2)
        self.assertNotEqual(quoted2, plaw2["sentence"], "the contradicting body must be visible to the parity gate")
        law7 = next(l for l in laws["universal"] if l["id"] == "LAW-07")
        self.assertEqual(corpus.body_section(self.repo, law7), (None, None, None, []))
        self.assertEqual(resolve_pointer(self.repo, "rules/x.md"), self.repo / ".claude/rules/x.md")

    def test_catalog_families_and_classes(self):
        cat = corpus.catalog(self.repo)
        self.assertEqual([f["name"] for f in cat["families"]], ["runtime", "data"])
        self.assertEqual(cat["families"][1]["surface"], ["**/migrations/**", "**/*.sql"])
        self.assertEqual([d["id"] for d in cat["dcs"]], ["DC-18", "DC-27", "DC-29"])
        self.assertEqual(cat["dcs"][1]["gate"], "scripts/validate-migrations.sh")
        self.assertEqual(cat["dcs"][2]["paths"], ["*"])

    def test_resolver_axes(self):
        res = corpus.applicable(self.repo, {"phase": "IMPLEMENT", "command": "implement", "framework": ["fastapi"]})
        names = {r["name"] for r in res["active"]["instructions"]}
        self.assertEqual(names, {"Factory-implement-build"})
        rules = {r["name"] for r in res["active"]["rules"]}
        self.assertIn("architecture.md", rules)
        self.assertIn("protected-code.md", rules, "path_glob resolved against the tracked tree")
        self.assertNotIn("python.md", rules, "framework axis must AND with path_glob")
        ex = {e["name"]: e["reason"] for e in res["excluded"]}
        self.assertTrue(any("frontmatter-parse-error" in v for k, v in ex.items() if k.endswith("broken.md")))
        self.assertTrue(ex[".claude/instructions/Factory-qa-verify.instructions.md"].startswith("phase="))
        self.assertEqual(len(res["active"]["laws"]), 5)
        self.assertEqual(len(res["discovery_hash"]), 8)

    def test_command_axis_with_empty_context_never_raises(self):
        # the pre-edit delivery passes an empty context: an entry whose first axis is `command` must simply not match
        active, why = corpus.matches({"command": ["push"]}, {}, [])
        self.assertFalse(active); self.assertIn("command=push", why)
        text, _ = corpus.digest(self.repo, ["src/app.py"], 6000)
        self.assertIn("DC-18", text)
        self.assertTrue(corpus.matches({"command": ["/implement --build"]}, {"command": "implement"}, [])[0], "documented form matches the command name")
        self.assertTrue(corpus.matches({"command": ["implement"]}, {"command": "/implement --refine"}, [])[0])
        self.assertEqual(corpus.matches({"bogus": ["x"]}, {"phase": "QA"}, [])[1], "applicable-when-invalid: bogus")

    def test_scope_and_change_type_axes(self):
        rules = lambda ctx: {r["name"] for r in corpus.applicable(self.repo, ctx)["active"]["rules"]}
        self.assertIn("React.md", rules({"scope": "frontend-only", "change_type": "feature"}))
        self.assertNotIn("React.md", rules({"scope": "backend-only", "change_type": "feature"}))
        self.assertNotIn("React.md", rules({"scope": "frontend-only", "change_type": "fix"}), "axes AND together")
        self.assertIn("ci-cd.md", rules({}), "path_glob .github/** resolved against the tracked tree")

    def test_excluded_reason_names_the_filter_that_failed(self):
        res = corpus.applicable(self.repo, {"agent": "ARCH"}, ["src/app.py"])
        reasons = {e["name"]: e["reason"] for e in res["excluded"]}
        self.assertEqual(reasons["DC-18"], "agent not in applicable_to")
        self.assertEqual(reasons["DC-27"], "paths/family do not match")

    def test_discovery_hash_covers_laws_and_classes(self):
        before = corpus.applicable(self.repo, {"phase": "QA"})["discovery_hash"]
        cat = self.repo / ".claude/rules/defect-prevention.md"
        cat.write_text(cat.read_text() + "| DC-30 | `runtime` | A new class. | `—` | `src/**` | DEV | WARNING |\n", encoding="utf-8")
        self.assertNotEqual(before, corpus.applicable(self.repo, {"phase": "QA"})["discovery_hash"], "a new DC changes the roll-call hash")

    def test_catalog_shape_is_fail_closed(self):
        cat = self.repo / ".claude/rules/defect-prevention.md"
        base = cat.read_text()
        cat.write_text(base + "| DC-31 | `runtime` | six columns | `—` | `src/**` | DEV |\n", encoding="utf-8")
        with self.assertRaisesRegex(GateFault, "DC-31 has 6 columns"):
            corpus.catalog(self.repo)
        cat.write_text(base + "| DC-32 | `ghost` | unknown family | `—` | `src/**` | DEV | WARNING |\n", encoding="utf-8")
        with self.assertRaisesRegex(GateFault, "family `ghost`"):
            corpus.catalog(self.repo)
        cat.write_text(base + "| DC-33 | `runtime` | no paths | `—` | — | DEV | WARNING |\n", encoding="utf-8")
        with self.assertRaisesRegex(GateFault, "no Paths"):
            corpus.catalog(self.repo)

    def test_law_without_pointer_is_refused_and_records_read_after_pointer(self):
        with self.assertRaisesRegex(GateFault, "no `Body:` pointer"):
            corpus.parse_law_list("## Governance Rules\n1. **[LAW-99] X** — S.\n## Y\n")
        with self.assertRaisesRegex(GateFault, "pre-index law shape"):
            corpus.parse_law_list("## Governance Rules\n1. **[LAW-99] X**: old shape body.\n## Y\n")
        s, b, r = corpus._entry_from_rest("Sentence mentions Records: nothing. Body: `inline`. Records: `ADR-1`.")
        self.assertEqual((b, r), ("inline", ["ADR-1"]))
        self.assertTrue(s.startswith("Sentence mentions Records: nothing"))
        pairs = corpus.law_sentences("## Governance Rules\n1. **[LAW-99] X** — No pointer here.\n## Y\n")
        self.assertEqual(pairs, [("LAW-99", "No pointer here.")], "the ceremony gate still sees the sentence of a malformed entry")

    def test_parity_finds_every_way_a_body_can_lie(self):
        problems = corpus.parity(self.repo)
        self.assertTrue(any(p.startswith("PLAW-02") and "differs" in p for p in problems), "contradicting quote")
        write(self.repo / ".claude/rules/dup.md", "---\ndescription: d\napplicable_when:\n  always: true\n---\n## [PLAW-01] KISS & DRY\n> Every solution is the simplest one that satisfies the specification, written once.\n")
        write(self.repo / ".claude/rules/orphan.md", "---\ndescription: o\napplicable_when:\n  always: true\n---\n## [PLAW-09] Ghost\n> A body with no index entry.\n")
        problems = corpus.parity(self.repo)
        self.assertTrue(any("PLAW-01: 2 body sections" in p for p in problems), "one body per law")
        self.assertTrue(any("PLAW-09" in p and "orphan" in p for p in problems))
        (self.repo / ".claude/rules/stateless.md").unlink()
        self.assertTrue(any("PLAW-02" in p and "does not resolve" in p for p in corpus.parity(self.repo)))

    def test_resolver_by_paths(self):
        res = corpus.applicable(self.repo, {}, ["src/app.py"])
        self.assertEqual([f["name"] for f in res["active"]["families"]], ["runtime"])
        self.assertEqual({d["id"] for d in res["active"]["dcs"]}, {"DC-18", "DC-29"})
        res = corpus.applicable(self.repo, {}, ["src/migrations/001.sql"])
        self.assertEqual({f["name"] for f in res["active"]["families"]}, {"runtime", "data"})
        self.assertIn("DC-27", {d["id"] for d in res["active"]["dcs"]})
        res = corpus.applicable(self.repo, {"agent": "ARCH"}, ["src/app.py"])
        self.assertEqual({d["id"] for d in res["active"]["dcs"]}, set(), "applicable_to filters by agent")

    def test_rollcall_shape(self):
        text = corpus.rollcall(corpus.applicable(self.repo, {"phase": "QA"}), "qa", "FEAT-1")
        for needle in ("📋 Applicability Roll-Call — qa · FEAT-1", "ACTIVE LAWS (5)", "ACTIVE DCs", "UNREADABLE (1)", "broken.md", "EXCLUDED (", "Discovery hash:"):
            self.assertIn(needle, text)

    def test_digest_respects_budget_in_bytes(self):
        full, fp_full = corpus.digest(self.repo, ["src/app.py", "src/migrations/001.sql"], 6000)
        self.assertIn("family runtime", full)
        self.assertIn("DC-27", full)
        self.assertIn("read .claude/rules/protected-code.md", full, "path-bound rule pointer for the .py file")
        self.assertNotIn("architecture.md", full, "always-rules are in the snapshot, not re-delivered")
        self.assertIn("rule .claude/rules/broken.md unreadable", full, "an unreadable rule is said, never silently dropped")
        cat = self.repo / ".claude/rules/defect-prevention.md"
        cat.write_text(cat.read_text() + "| DC-40 | `runtime` | " + "— multibyte dashes — " * 12 + " | `—` | `src/**` | DEV | WARNING |\n", encoding="utf-8")
        for b in list(range(150, 420, 37)) + [60]:   # 60 < the head with its attributes: the envelope drops them and still fits
            text, _ = corpus.digest(self.repo, ["src/migrations/001.sql"], b)
            self.assertLessEqual(len(text.encode()), b, f"budget {b} is in bytes")
            self.assertTrue(text.startswith("<governance-at-edit") and text.endswith("</governance-at-edit>"))
        text, _ = corpus.digest(self.repo, ["src/app.py"], 400)
        self.assertTrue("more — read" in text or "\n…\n" in text, "what was cut is counted, never silent (the note, or its one-glyph form when even the note does not fit)")
        _, fp_a = corpus.digest(self.repo, ["src/a.py"], 6000)
        _, fp_b = corpus.digest(self.repo, ["src/b.py"], 6000)
        self.assertEqual(fp_a, fp_b, "the same delivered set dedupes across paths")


class Retired(unittest.TestCase):
    def test_ratchet_red_and_exemptions(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = fixture_repo(Path(tmp))
            hits = retired.scan(repo)
            paths = {h["path"] for h in hits}
            self.assertIn("docs/old.md", paths, "a retired term in the governed tree is red")
            self.assertNotIn("docs/legacy/x.md", paths, "declared exemption glob")
            self.assertNotIn("docs/project_log/evolutions/ADR-1.md", paths, "history is exempt by class")
            self.assertNotIn("config/quality.json", paths, "the declaration itself is exempt")
            self.assertIn("FAIL", retired.render(hits))
            (repo / "docs/old.md").write_text("clean\n", encoding="utf-8")
            self.assertEqual(retired.scan(repo), [])
            write(repo / "src/note.md", f"{RETIRED} in src\n")
            write(repo / "vendor/x.lock", f"{RETIRED} in a lock\n")
            subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
            self.assertIn("src/note.md", {h["path"] for h in retired.scan(repo)})
            (repo / "config/coherence-context.json").write_text(json.dumps({"context": "downstream", "audit": {"root_sets": ["docs/"], "exclusions": ["*.lock"]}}), encoding="utf-8")
            self.assertEqual({h["path"] for h in retired.scan(repo)}, set(), "roots limit the scan; *.lock excluded")
            (repo / "config/quality.json").write_text(json.dumps({"retired_terms": [{"term": "x"}]}), encoding="utf-8")
            with self.assertRaisesRegex(GateFault, "needs `term` and `record`"):
                retired.scan(repo)


class Budget(unittest.TestCase):
    def test_missing_key_is_a_red_verdict_and_corrupt_config_a_fault(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = fixture_repo(Path(tmp))
            (repo / "config/quality.json").write_text("{}", encoding="utf-8")
            rows = budget.measure(repo)
            self.assertTrue(all(not r["ok"] and "missing" in r["fault"] for r in rows.values()), "every missing key is a red row")
            with self.assertRaises(GateFault):
                key(repo, "budgets", required=True)
            (repo / "config/quality.json").write_text("{not json", encoding="utf-8")
            with self.assertRaisesRegex(GateFault, "not readable JSON"):
                budget.measure(repo)

    def test_measures_real_producers_and_flags_overflow(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = fixture_repo(Path(tmp))
            write(repo / "scripts/validate-governance.sh", "#!/usr/bin/env bash\n[ \"$1\" = --banner ] && printf 'Governance loaded: x\\n'\n")
            write(repo / "scripts/governance-onprompt.sh", "#!/usr/bin/env bash\n[ \"${GOVERNANCE_ONPROMPT_WORST_CASE:-}\" = 1 ] && head -c 20000 /dev/zero | tr '\\0' 'y'\nexit 0\n")
            import shutil; shutil.copytree(HERE, repo / "scripts/gates", ignore=shutil.ignore_patterns("__pycache__", "test_*"))
            shutil.copy(HERE.parent / "gate.py", repo / "scripts/gate.py")
            write(repo / ".claude/hooks/deliver-governance.sh", "#!/usr/bin/env bash\npython3 scripts/gate.py --repo . deliver --hook-json\n")   # the REAL delivery, so the dedupe pointer would be measurable
            write(repo / ".context/governance_snapshot.md", "x" * 100)
            rows = budget.measure(repo)
            self.assertEqual(rows["session_start"]["bytes"], len("Governance loaded: x\n"))
            self.assertTrue(rows["session_start"]["ok"])
            self.assertEqual(rows["prompt_submit"]["bytes"], 20000)
            self.assertFalse(rows["prompt_submit"]["ok"], "the real producer overflowed its key — red")
            self.assertEqual(rows["snapshot"]["bytes"], 100)
            self.assertIn("OVERFLOW", budget.render(rows))
            cat = corpus.catalog(repo)
            self.assertEqual(budget.worst_case_path(cat), "src/x/migrations/x/x.py", "the path under the most globs at once")
            tie = {"families": [{"name": "a", "surface": ["**/*.zz"], "invariant": "x"}, {"name": "b", "surface": ["**/*.aa"], "invariant": "y"}], "dcs": []}
            self.assertEqual(budget.worst_case_path(tie), "x/x.aa", "equal scores resolve to the sorted-first candidate, every run")
            self.assertGreater(rows["pre_edit"]["bytes"], 150, "the real payload was measured")
            self.assertEqual(rows["pre_edit"]["bytes"], budget.measure(repo)["pre_edit"]["bytes"], "a fresh session per run: never the dedupe pointer")
            self.assertFalse(list((repo / ".claude/state").glob("governance-delivered-budget-*")), "no marker left behind")
            write(repo / ".claude/hooks/deliver-governance.sh", "#!/usr/bin/env bash\nexit 0\n")
            rows = budget.measure(repo)
            self.assertFalse(rows["pre_edit"]["ok"], "an empty pre-edit delivery is a dead producer, never within budget")
            self.assertIn("EMPTY", budget.render(rows))
            write(repo / "scripts/validate-governance.sh", "#!/usr/bin/env bash\necho boom >&2\nexit 1\n")
            rows = budget.measure(repo)
            self.assertFalse(rows["session_start"]["ok"]); self.assertIn("exited 1: boom", rows["session_start"]["fault"])
            self.assertIn("RED — producer", budget.render(rows))
            (repo / "scripts/governance-onprompt.sh").unlink()
            rows = budget.measure(repo)
            self.assertFalse(rows["prompt_submit"]["ok"]); self.assertIn("producer absent", rows["prompt_submit"]["fault"])
            (repo / "config/quality.json").write_text(json.dumps({"budgets": {"session_start": 1}}), encoding="utf-8")
            rows = budget.measure(repo)
            self.assertFalse(rows["pre_edit"]["ok"]); self.assertIn("key budgets.pre_edit missing", rows["pre_edit"]["fault"])


class Coherence(unittest.TestCase):
    def _repo(self, tmp, branch="feature/F-001-x"):
        repo = fixture_repo(Path(tmp))
        for rel in (".claude/skills/factory-pr-review/scripts/detect_change_type.py", ".claude/skills/factory-code-review/scripts/code_review_hash.py"):
            src = HERE.parent.parent / rel
            if src.is_file():
                write(repo / rel, src.read_text(encoding="utf-8"))
        self._commit(repo, "pipeline")
        subprocess.run(["git", "-C", str(repo), "branch", "-M", "main"], check=True)
        subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/main", "HEAD"], check=True)
        subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", branch], check=True)
        return repo

    def _commit(self, repo, msg):
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", msg], check=True)

    def test_tree_hash_moves_only_with_its_subject(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            c = coherence.certify(repo, "tree", paths=["src/**"])
            self.assertEqual(c["subject"], "tree"); self.assertEqual(c["paths"], ["src/**"])
            self.assertEqual(c["hash"], coherence.certify(repo, "tree", paths=["src/**"])["hash"], "deterministic")
            write(repo / "docs/x.md", "docs only\n"); self._commit(repo, "docs")
            self.assertEqual(c["hash"], coherence.certify(repo, "tree", paths=["src/**"])["hash"], "a change outside the paths does not move the subject")
            write(repo / "src/app.py", "print(2)\n"); self._commit(repo, "code")
            self.assertNotEqual(c["hash"], coherence.certify(repo, "tree", paths=["src/**"])["hash"], "a change under the paths moves the subject")
            with self.assertRaisesRegex(GateFault, "needs the paths"):
                coherence.certify(repo, "tree")
            with self.assertRaisesRegex(GateFault, "matches the certified paths"):
                coherence.certify(repo, "tree", paths=["nope/**"])
            with self.assertRaisesRegex(GateFault, "unknown certification subject"):
                coherence.certify(repo, "blob")
            self.assertEqual(coherence.certify(repo, "tree", paths=["src"])["hash"], coherence.certify(repo, "tree", paths=["src/**"])["hash"], "a bare directory covers what is below it")

    def test_worktree_hash_sees_what_a_critic_would_do(self):
        """The guard around a read-only run: an unstaged edit, a new untracked file, a deletion — each moves the
        worktree hash; the index hash (tree) sees none of them."""
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            idx = coherence.certify(repo, "tree", paths=["src/**"])["hash"]
            w0 = coherence.certify(repo, "worktree", paths=["src/**"])["hash"]
            self.assertEqual(w0, coherence.certify(repo, "worktree", paths=["src"])["hash"], "deterministic; a bare directory covers what is below it")
            write(repo / "src/app.py", "print(9)  # unstaged\n")
            w1 = coherence.certify(repo, "worktree", paths=["src/**"])["hash"]
            self.assertNotEqual(w0, w1, "an unstaged edit moves the worktree hash")
            self.assertEqual(idx, coherence.certify(repo, "tree", paths=["src/**"])["hash"], "…and the index hash does not — which is why the guard reads the worktree")
            write(repo / "src/new.py", "new\n")
            w2 = coherence.certify(repo, "worktree", paths=["src/**"])["hash"]
            self.assertNotEqual(w1, w2, "a new untracked file moves it")
            write(repo / "docs/x.md", "elsewhere\n")
            self.assertEqual(w2, coherence.certify(repo, "worktree", paths=["src/**"])["hash"], "a change outside the paths does not")
            (repo / "src/new.py").unlink(); (repo / "src/app.py").unlink()
            self.assertNotEqual(w2, coherence.certify(repo, "worktree", paths=["src/**"])["hash"], "a deletion moves it")
            self.assertTrue(coherence.certify(repo, "worktree", paths=["nowhere/**"])["hash"], "a scope with no file yet is a hash, not a fault: the run is still guarded")
            with self.assertRaisesRegex(GateFault, "needs the paths"):
                coherence.certify(repo, "worktree")

    def test_certify_diff_fixes_the_file_set_at_certify_time(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            write(repo / "src/feat.py", "def f(): return 1\n"); self._commit(repo, "feat")
            c = coherence.certify(repo, "diff", base="origin/main")
            self.assertEqual(c["paths"], ["src/feat.py"], "the code/test files of the diff, stored explicitly")
            self.assertEqual(c["hash"], coherence.tree_hash(repo, c["paths"]), "one hash function for both subjects")
            self.assertEqual(c, coherence.certify(repo, "diff", base="origin/main"), "deterministic")
            write(repo / "src/other.py", "x = 1\n"); self._commit(repo, "another file")
            self.assertEqual(c["hash"], coherence.tree_hash(repo, c["paths"]), "a new file elsewhere does not move the certified set")
            write(repo / "src/feat.py", "def f(): return 2\n"); self._commit(repo, "moved")
            self.assertNotEqual(c["hash"], coherence.tree_hash(repo, c["paths"]), "a change to a certified file moves it")
            with self.assertRaisesRegex(GateFault, "classifier failed"):
                coherence.certify(repo, "diff", base="no-such-ref")
            (repo / ".claude/skills/factory-pr-review/scripts/detect_change_type.py").unlink()
            with self.assertRaisesRegex(GateFault, "not delivered"):
                coherence.certify(repo, "diff", base="origin/main")

    def test_currency_scope_supersession_and_verdicts(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp, "feature/F-001-x")
            fresh = coherence.certify(repo, "tree", paths=["src/**"])["hash"]
            cert = f"certifies:\n  subject: tree\n  paths: [\"src/**\"]\n  hash: \"{fresh}\"\n"
            write(repo / "docs/spec/F-001/qa/qa_report_final_20260101.md", f"---\nstatus: APPROVED\nverdict: APPROVED ✅\n{cert}---\n")
            write(repo / "docs/spec/F-001/qa/qa_report_final_20260201.md", f"---\nstatus: DRAFT\n---\n")   # newest, not terminal → owes nothing yet
            write(repo / "docs/spec/F-001/qa/qa_report_INC-1_20260101.md", "---\nstatus: approved\n---\n")  # lower-case terminal, no certifies
            write(repo / "docs/spec/F-001/review/peer_review_20260101.md", "---\nstatus: APPROVED\ncertifies:\n  subject: tree\n  paths: \"src/**\"\n  hash: \"stale000\"\n---\n")
            write(repo / "docs/spec/F-001/sec_audit.md", "---\nstatus: SECURE\ncertifies:\n  subject: tree\n  paths: [\"nope/**\"]\n  hash: \"x\"\n---\n")
            write(repo / "docs/spec/F-001/smoke_e2e_report.md", "---\noverall_verdict: PASS\ncertifies: \"broken\n---\n")
            self._commit(repo, "verdicts")
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "main"], check=True)
            write(repo / "docs/spec/F-002/qa/qa_report_final_20260101.md", "---\nstatus: APPROVED\n---\n")          # another feature, merged earlier: out of scope
            self._commit(repo, "F-002 verdict on main")
            subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/main", "HEAD"], check=True)
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "feature/F-001-x"], check=True)
            subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "merge", "-q", "--no-edit", "main"], check=True)
            findings, faults = coherence.currency(repo, "origin/main")
            reasons = {f["path"]: f["reason"] for f in findings}
            self.assertEqual(faults, [])
            self.assertNotIn("docs/spec/F-001/qa/qa_report_final_20260101.md", reasons, "superseded by the newer report of the same kind — never judged")
            self.assertNotIn("docs/spec/F-001/qa/qa_report_final_20260201.md", reasons, "a draft owes no certification")
            self.assertIn("certifies-missing", reasons["docs/spec/F-001/qa/qa_report_INC-1_20260101.md"], "lower-case terminal is still terminal")
            self.assertIn("STALE", reasons["docs/spec/F-001/review/peer_review_20260101.md"], "a string paths value is a one-item list")
            self.assertIn("matches the certified paths", reasons["docs/spec/F-001/sec_audit.md"], "a certification over nothing is red")
            self.assertIn("unreadable", reasons["docs/spec/F-001/smoke_e2e_report.md"], "invalid YAML for both parsers")
            self.assertNotIn("docs/spec/F-002/qa/qa_report_final_20260101.md", reasons, "another feature's verdict is not this push's business")
            # on an unrelated branch after the merge, F-001's verdicts are not judged (never STALE forever)
            subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/main", "HEAD"], check=True)
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "fix/other"], check=True)
            write(repo / "src/app.py", "print(9)\n"); self._commit(repo, "moves src")
            findings, _ = coherence.currency(repo, "origin/main")
            self.assertEqual(findings, [], "post-merge, unrelated work never inherits stale verdicts")
            # …but a branch on the same feature that moves a certified file sees its verdict go STALE
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "feature/F-001-inc-2-y"], check=True)
            (repo / "docs/spec/F-001/qa/qa_report_final_20260201.md").unlink(); self._commit(repo, "drop draft")
            findings, _ = coherence.currency(repo, "origin/main")
            self.assertIn("STALE", {f["path"]: f["reason"] for f in findings}.get("docs/spec/F-001/qa/qa_report_final_20260101.md", ""))
            self.assertIn("FAIL", coherence.render("currency", findings))
            (repo / ".claude/skills/factory-pr-review/scripts/detect_change_type.py").unlink()   # pipeline gone: tree still judges; git down would be a fault
            findings, faults = coherence.currency(repo, "origin/main")
            self.assertTrue(findings and not faults)
            write(repo / ".gitignore", "docs/spec/**/qa/qa_report_*.md\n"); self._commit(repo, "ignore")
            write(repo / "docs/spec/F-001/qa/qa_report_final_20260301.md", "---\nstatus: APPROVED\n---\n")   # ignored, never tracked
            reasons = {f["path"]: f["reason"] for f in coherence.currency(repo, "origin/main")[0]}
            self.assertIn("not tracked", reasons["docs/spec/F-001/qa/qa_report_final_20260301.md"], "a gitignored verdict is red, never invisible")

    def test_manifest_parity_red_on_drift_and_unreadable(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            write(repo / "config/coherence-context.json", json.dumps({"context": "downstream", "audit": {"manifest_paths": {"primary": "docs/project_log/governance_versions.json"}}}))
            write(repo / "docs/project_log/governance_versions.json", json.dumps({"templates": {
                "rules/architecture.md": {"version": "1.2.0", "target": ".claude/rules/architecture.md"},
                "rules/stateless.md": {"version": "1.0.0", "target": ".claude/rules/stateless.md"},
                "rules/quoted.md": {"version": "1.0.0", "target": ".claude/rules/quoted.md"},
                "rules/broken.md": {"version": "1.0.0", "target": ".claude/rules/broken.md"}},
                "framework_core": {"skills/x/SKILL.md": {"version": "2.0.0", "path": ".claude/skills/x/SKILL.md"}}}))
            write(repo / ".claude/rules/architecture.md", "---\nversion: 1.1.0\napplicable_when:\n  always: true\n---\n")
            write(repo / ".claude/rules/stateless.md", "---\nversion: 1.0.0   # inline comment\napplicable_when:\n  always: true\n---\n")
            (repo / ".claude/rules/quoted.md").write_bytes(b'---\r\nversion: "1.0.0"\r\napplicable_when:\r\n  always: true\r\n---\r\n')
            write(repo / ".claude/skills/x/SKILL.md", "---\nname: x\nversion: 1.9.0\n---\n")
            findings, stats = coherence.manifest_parity(repo)
            reasons = {f["path"]: f["reason"] for f in findings}
            self.assertIn("1.1.0 ≠ manifest 1.2.0", reasons[".claude/rules/architecture.md"])
            self.assertNotIn(".claude/rules/stateless.md", reasons, "inline comment stripped by the one parser")
            self.assertNotIn(".claude/rules/quoted.md", reasons, "quoted + CRLF value equals the manifest digit")
            self.assertIn("1.9.0 ≠ manifest 2.0.0", reasons[".claude/skills/x/SKILL.md"], "framework_core entries with a `path` are compared too")
            self.assertIn("unreadable", reasons[".claude/rules/broken.md"])
            self.assertEqual(stats["compared"], 4)
            (repo / "docs/project_log/governance_versions.json").write_text(json.dumps({"files": {}}), encoding="utf-8")
            with self.assertRaisesRegex(GateFault, "no `templates` section"):
                coherence.manifest_parity(repo)
            (repo / "docs/project_log/governance_versions.json").write_text("{nope", encoding="utf-8")
            with self.assertRaisesRegex(GateFault, "not readable JSON"):
                coherence.manifest_parity(repo)


class Branch(unittest.TestCase):
    """EVOL-045: every class of the grammar, the one diff base (fail-closed), the surface ceiling seen red."""

    def _repo(self, tmp):
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text())
        q["surface"] = {"ceiling_files": 3, "ceiling_lines": 20, "escapes": ["generated-code", "lockfile"], "runtime_surface": []}
        write(repo / "config/quality.json", json.dumps(q))
        write(repo / "docs/spec/F-001/increment_plan.md", "### INC-1 — a\n- **Sub-increments:**\n  - SUB-1-1: x · branch feature/F-001-inc-1-a-sub-1\n  - SUB-1-2: y\n### INC-2 — b\n- **Sub-increments:** none\n")
        self._commit(repo, "plan")
        subprocess.run(["git", "-C", str(repo), "branch", "-M", "main"], check=True)
        subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/main", "HEAD"], check=True)
        return repo

    def _commit(self, repo, msg):
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", msg], check=True)

    def test_branch_classes_and_train_protection(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            cases = {"main": ("protected", True), "release/1.2": ("protected", True), "hotfix": ("protected", True),
                     "feature/F-001-inc-1-a": ("train", True), "feature/F-001-inc-1-a-sub-2": ("sub-increment", False),
                     "feature/F-001-inc-2-b": ("increment", False), "feature/F-001-inc-3-c": ("increment", False),
                     "feature/F-001-login": ("feature", False), "feature/EVOL-045-increment-trains": ("feature", False),
                     "epic/EPIC-1-foundation": ("epic", False), "fix/x": ("fix", False), "bugfix/x": ("fix", False),
                     "feat/x": ("feature", False), "breaking/x": ("breaking", False),   # the kinds CLAUDE.md INVARIANT 1 names
                     "feature/F-001-inc-1-add-sub-1": ("sub-increment", False),         # a slug never ends in -sub-<digits>: reserved
                     "hotfix/x": ("fix", False), "docs/x": ("docs", False), "chore/x": ("chore", False),
                     "weird": ("unknown", False), "feature/lowercase-id": ("unknown", False)}
            for name, (cls, prot) in cases.items():
                info = branch.branch_class(repo, name)
                self.assertEqual((info["class"], info["protected"]), (cls, prot), name)
            self.assertEqual(branch.branch_class(repo, "feature/F-001-inc-1-a-sub-2")["train"], "feature/F-001-inc-1-a")
            self.assertEqual(branch.branch_class(repo, "feature/F-001-inc-1-a-sub-2")["feature_id"], "F-001", "the id stops before -inc-")
            self.assertEqual(branch.train_of("feature/F-001-inc-1-a"), None)
            self.assertNotEqual(branch.branch_class(repo, "feature/F-001-inc-1-a-sub-0")["class"], "sub-increment", "M starts at 1")
            # the template's own example line must be read as a declaration (the regex is tested against the shape BLUEPRINT copies)
            tmpl = (HERE.parent.parent / ".context/templates/architect/increment_plan_template.md").read_text(encoding="utf-8")
            example = [seg for seg in tmpl.split("`") if seg.startswith("- SUB-1-{M}:")][0]
            example = example.replace("{M}", "1").replace("{{FEATURE_ID}}", "F-002").replace("{{slug}}", "a")
            write(repo / "docs/spec/F-002/increment_plan.md", "### INC-1 — a\n- **Sub-increments:**\n  " + example + "\n")
            self.assertEqual(branch.branch_class(repo, "feature/F-002-inc-1-a")["class"], "train", "the template example declares a train")
            write(repo / "docs/spec/F-003/increment_plan.md", "### INC-1 — a\n- **Sub-increments:**\n  - **SUB-1-1** — scope\n")
            self.assertEqual(branch.branch_class(repo, "feature/F-003-inc-1-a")["class"], "train", "a bold id with an em dash declares too")

    def test_diff_base_is_one_and_fail_closed(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            with self.assertRaisesRegex(GateFault, "train `feature/F-001-inc-1-a` is not on origin.*push -u origin feature/F-001-inc-1-a"):
                branch.diff_base(repo, "feature/F-001-inc-1-a-sub-1")   # the train exists nowhere on the remote: said in plain language
            subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/feature/F-001-inc-1-a", "HEAD"], check=True)
            self.assertEqual(branch.diff_base(repo, "feature/F-001-inc-1-a-sub-2"), "origin/feature/F-001-inc-1-a", "a sub-increment measures against its train")
            for b in ("feature/F-001-inc-1-a", "feature/F-001-inc-2-b", "feature/F-001-login", "fix/x", "docs/x", "chore/x", "epic/EPIC-1-x"):
                self.assertEqual(branch.diff_base(repo, b), "origin/main", b)
            self.assertEqual(branch.diff_base(repo, "main"), "origin/main")
            with self.assertRaisesRegex(branch.UnknownBranch, "matches no class"):
                branch.diff_base(repo, "weird")
            write(repo / ".claude/rules/branching.md", "---\ndefault_base_branch: develop\n---\n")
            with self.assertRaisesRegex(GateFault, "base branch `develop` is not on origin"):
                branch.diff_base(repo, "fix/x")
            subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/develop", "HEAD"], check=True)
            self.assertEqual(branch.diff_base(repo, "fix/x"), "origin/develop", "default_base_branch from the branching rule is honoured")
            write(repo / ".claude/rules/branching.md", "---\ndefault_base_branch: [unclosed\n---\n")
            with self.assertRaisesRegex(GateFault, "branching.md cannot be read"):
                branch.diff_base(repo, "fix/x")   # an unreadable rule is a fault, never a silent main
            write(repo / ".claude/rules/branching.md", "---\ndefault_base_branch: develop\n---\n")
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "feature/F-001-inc-1-a-sub-1"], check=True)
            self.assertEqual(branch.diff_base(repo), "origin/feature/F-001-inc-1-a", "the current branch is classified when none is given")

    def test_surface_ceiling_escapes_and_train_base(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "feature/F-001-login"], check=True)
            s = branch.surface(repo)
            self.assertEqual((s["files"], s["lines"], s["ok"], s["base"]), (0, 0, True, "origin/main"))
            write(repo / "src/a.py", "1\n"); write(repo / "src/b.py", "2\n"); self._commit(repo, "two files")
            s = branch.surface(repo)
            self.assertEqual((s["files"], s["lines"], s["ok"]), (2, 2, True))
            write(repo / "src/c.py", "3\n"); write(repo / "src/d.py", "4\n"); self._commit(repo, "four files")
            s = branch.surface(repo)
            self.assertFalse(s["ok"]); self.assertIn("exceeds the ceiling", s["reason"]); self.assertIn("surface.ceiling_files", s["reason"])
            subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "--allow-empty", "-m", "x\n\nSurface-Escape: nope"], check=True)
            s = branch.surface(repo)
            self.assertFalse(s["ok"]); self.assertIn("unknown Surface-Escape `nope`", s["reason"]); self.assertIn("generated-code, lockfile", s["reason"])
            subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "--allow-empty", "-m", "x\n\nSurface-Escape: generated-code"], check=True)
            s = branch.surface(repo)
            self.assertFalse(s["ok"], "one unknown term in the range still fails — the vocabulary is closed")
            subprocess.run(["git", "-C", str(repo), "reset", "-q", "--hard", "HEAD~2"], check=True)
            subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "--allow-empty", "-m", "x\n\nSurface-Escape: lockfile"], check=True)
            s = branch.surface(repo)
            self.assertTrue(s["ok"]); self.assertEqual(s["escape"], "lockfile"); self.assertTrue(s["over"])
            # lines ceiling, on a single file
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "feature/F-001-inc-2-b", "main"], check=True)
            write(repo / "src/big.py", "x\n" * 30); self._commit(repo, "big")
            s = branch.surface(repo)
            self.assertFalse(s["ok"]); self.assertEqual((s["files"], s["lines"]), (1, 30))
            # a sub-increment is measured against its train, not main
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "feature/F-001-inc-1-a", "main"], check=True)
            for i in range(4):
                write(repo / f"src/t{i}.py", "t\n")
            self._commit(repo, "train content")
            subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/feature/F-001-inc-1-a", "HEAD"], check=True)
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "feature/F-001-inc-1-a-sub-1"], check=True)
            write(repo / "src/s.py", "s\n"); self._commit(repo, "sub")
            s = branch.surface(repo)
            self.assertEqual((s["base"], s["files"], s["ok"]), ("origin/feature/F-001-inc-1-a", 1, True))
            self.assertEqual(branch.surface(repo, base="origin/main")["files"], 5, "against main the train content would count")
            # the train itself is exempt by class: its closing PR is the sum of gated sub-increment PRs
            t = branch.surface(repo, base="origin/main", branch="feature/F-001-inc-1-a")
            self.assertTrue(t["ok"]); self.assertEqual(t["class"], "train"); self.assertIn("each sub-increment PR", t["reason"])
            self.assertTrue(branch.render_surface(t).startswith("surface: ok — train"))
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "feature/F-001-inc-1-a"], check=True)
            self.assertTrue(branch.surface(repo)["ok"], "on the train, no --base: exempt")
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "feature/F-001-inc-1-a-sub-1"], check=True)
            q = json.loads((repo / "config/quality.json").read_text()); del q["surface"]["ceiling_lines"]
            write(repo / "config/quality.json", json.dumps(q))
            with self.assertRaisesRegex(GateFault, "surface.ceiling_lines"):
                branch.surface(repo)


class Profile(unittest.TestCase):
    """EVOL-046: one mode key (fail-closed), one profile per control point, members by property, all-report, one definition."""

    def _repo(self, tmp, mode="development"):
        repo = fixture_repo(Path(tmp))
        write(repo / "docs/spec/F-001/increment_plan.md", "### INC-1 — a\n- **Sub-increments:**\n  - SUB-1-1: x · status: READY\n")
        if mode is not None:
            write(repo / "docs/project_log/governance_versions.json", json.dumps({"framework_version": "7.3.0", "delivery_mode": mode, "templates": {}}))
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "plan"], check=True)
        subprocess.run(["git", "-C", str(repo), "branch", "-M", "main"], check=True)
        for ref in ("main", "feature/F-001-inc-1-a"):
            subprocess.run(["git", "-C", str(repo), "update-ref", f"refs/remotes/origin/{ref}", "HEAD"], check=True)
        return repo

    def test_mode_is_one_key_and_fails_closed(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            self.assertEqual(profile.mode(repo)["mode"], "development")
            write(repo / "docs/project_log/governance_versions.json", json.dumps({"delivery_mode": "fast"}))
            m = profile.mode(repo); self.assertEqual(m["mode"], "production"); self.assertIn("not one of", m["reason"])
            write(repo / "docs/project_log/governance_versions.json", json.dumps({"framework_version": "1"}))
            self.assertEqual(profile.mode(repo)["mode"], "production", "absent key = strictest")
            write(repo / "docs/project_log/governance_versions.json", "{not json")
            m = profile.mode(repo); self.assertEqual(m["mode"], "production"); self.assertIn("not readable", m["reason"])
            write(repo / "docs/project_log/governance_versions.json", "[1, 2]")
            self.assertEqual(profile.mode(repo)["mode"], "production", "valid JSON that is not an object = strictest, never an exception")
            (repo / "docs/project_log/governance_versions.json").unlink()
            self.assertEqual(profile.mode(repo)["mode"], "production", "absent manifest = strictest")
            write(repo / "docs/project_log/governance_versions.json", json.dumps({"delivery_mode": "production"}))
            os.environ["DELIVERY_MODE"] = "development"; os.environ["FACTORY_MODE"] = "development"
            try:
                self.assertEqual(profile.mode(repo)["mode"], "production", "no environment variable overrides the key")
            finally:
                del os.environ["DELIVERY_MODE"]; del os.environ["FACTORY_MODE"]

    def test_profile_per_control_point(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            self.assertEqual(profile.profile(repo, "feature/F-001-inc-1-a-sub-1")["profile"], "light", "a sub-increment to its train in development mode")
            for b in ("feature/F-001-inc-1-a", "feature/F-001-login", "fix/x", "main", "weird"):
                self.assertEqual(profile.profile(repo, b)["profile"], "full", b)
            write(repo / "docs/project_log/governance_versions.json", json.dumps({"delivery_mode": "production"}))
            pr = profile.profile(repo, "feature/F-001-inc-1-a-sub-1")
            self.assertEqual(pr["profile"], "full"); self.assertIn("production mode", pr["reason"])
            light = {m["member"] for m in profile.owed("light")}; full = {m["member"] for m in profile.owed("full")}
            self.assertTrue(light < full)
            self.assertFalse(any(m["needs_build"] or m["needs_database"] for m in profile.owed("light")), "light = no build, no database — by property")
            self.assertIn("tests", full - light); self.assertIn("seed-alignment", full - light); self.assertIn("surface", light)

    def test_run_reports_every_member_and_one_verdict(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "feature/F-001-inc-1-a-sub-1"], check=True)
            rep = profile.run(repo, only=["retired-terms", "manifest-parity", "surface"])
            self.assertEqual(rep["profile"], "light"); self.assertEqual(rep["base"], "origin/feature/F-001-inc-1-a")
            by = {r["member"]: r for r in rep["results"]}
            self.assertEqual(set(by), {"retired-terms", "manifest-parity", "surface"}, "every member reports — the run never stops at the first red")
            self.assertEqual(by["retired-terms"]["status"], "RED", "the fixture carries a retired term")
            self.assertEqual(by["surface"]["status"], "FAULT", "surface keys absent in the fixture = could not run, said")
            self.assertEqual(rep["verdict"], "RED"); self.assertIn("retired-terms", rep["summary"]); self.assertIn("surface", rep["summary"])
            text = profile.render(rep)
            self.assertIn("✗ retired-terms", text); self.assertIn("? surface", text); self.assertIn("skipped by the light profile", text); self.assertIn("tests", text)
            self.assertTrue(any(e["member"] == "code-review" for e in rep["owed_elsewhere"]), "agent-run members are owed, never silently dropped")
            rep = profile.run(repo, branch="nonsense", only=["retired-terms"])
            self.assertEqual(rep["verdict"], "RED"); self.assertIn("no diff base", rep["summary"])
            subprocess.run(["git", "-C", str(repo), "update-ref", "-d", "refs/remotes/origin/feature/F-001-inc-1-a"], check=True)
            rep = profile.run(repo, only=["retired-terms"])
            self.assertEqual(rep["verdict"], "RED"); self.assertIn("not on origin", rep["summary"], "a train not yet pushed: nothing measured = RED, never a pass")
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "--detach"], check=True)
            rep = profile.run(repo, only=["retired-terms"])
            self.assertEqual(rep["verdict"], "RED"); self.assertIn("detached HEAD", rep["summary"])
            rep = profile.run(repo, base="main", only=["retired-terms"])
            self.assertEqual(rep["verdict"], "RED"); self.assertIn("remote ref", rep["summary"], "a local base may be stale")
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "feature/F-001-inc-1-a-sub-1"], check=True)
            subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/feature/F-001-inc-1-a", "HEAD"], check=True)
            rep = profile.run(repo, only=["surface"])
            self.assertEqual(rep["verdict"], "FAULT"); self.assertNotIn(" —  · ", profile.render(rep)); self.assertTrue(rep["summary"].startswith("could not run"))
            rep = profile.run(repo, only=["surface", "retired-terms"])
            self.assertEqual([r["member"] for r in rep["results"]], ["retired-terms", "surface"], "a FAULT never stops the run: the later member still reports")
            self.assertEqual(rep["verdict"], "RED")
            rep = profile.run(repo, only=["adr-sync", "governance", "applicability"])   # the bash runner, a missing script, the meta-only member in a project
            by = {r["member"]: r for r in rep["results"]}
            self.assertEqual(by["adr-sync"]["status"], "RED"); self.assertIn("not delivered", by["adr-sync"]["tail"], "a member script missing in a project is a red on the delivery")
            self.assertEqual(by["governance"]["status"], "n/a", "a framework-only member is listed, never silently dropped")
            self.assertIn("applicability", by, "the applicability validator ships to projects and runs there")
            self.assertEqual(profile._cmd(repo, ["bash", "x", "--base", "{base_branch}"], "origin/feature/F-001-inc-1-a", "b")[-1], "feature/F-001-inc-1-a")
            self.assertEqual(profile._cmd(repo, ["bash", "x", "--base", "{base_branch}"], "refs/remotes/origin/main", "b")[-1], "main")

    def test_one_definition_scan(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            self.assertEqual(profile.one_definition(repo), [])
            write(repo / ".claude/hooks/x.sh", "#!/bin/bash\nPROTECTED_BRANCHES=\"main master\"\n# a comment naming (main|master) is fine\nref=\"${1#refs/heads/}\"; case \"$ref\" in main|master) exit 1;; esac\nfor p in main master develop; do :; done\n[[ \"$b\" == \"main\" ]] && exit 1\n")
            write(repo / ".github/workflows/ci.yml", "run: python3 -c \"import json; print(json.load(open('m.json'))['delivery_mode'])\"\n")
            write(repo / ".github/workflows/z.yaml", "env:\n  GATE_PROFILE=light\n  X: ${DELIVERY_MODE}\n")
            write(repo / "scripts/x.sh", "if [[ \"$b\" =~ ^(main|master|release) ]]; then exit 1; fi\n")
            f = profile.one_definition(repo)
            self.assertEqual(sorted((x["path"], x["line"]) for x in f),
                             sorted([(".claude/hooks/x.sh", 2), (".claude/hooks/x.sh", 4), (".claude/hooks/x.sh", 5), (".claude/hooks/x.sh", 6),
                                     (".github/workflows/ci.yml", 1), (".github/workflows/z.yaml", 2), (".github/workflows/z.yaml", 3), ("scripts/x.sh", 1)]))
            by = {(x["path"], x["line"]): x["reason"] for x in f}
            self.assertIn("branch-class --protected", by[(".claude/hooks/x.sh", 2)]); self.assertIn("gate.py profile", by[(".github/workflows/ci.yml", 1)])


class Runtime(unittest.TestCase):
    """EVOL-047: the positive trigger and the parity gate over the deploying jobs and their scripts."""

    def _repo(self, tmp, surface=None, workflows=None):
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text())
        q["surface"] = {"ceiling_files": 30, "ceiling_lines": 800, "escapes": [],
                        "runtime_surface": ["src/**", "scripts/**"] if surface is None else surface,
                        "always_deploy": [{"path": [".github/workflows/**", ".gitlab-ci*.yml", "Jenkinsfile*"], "reason": "workflow definitions"}, {"path": "config/quality.json", "reason": "gate input"}],
                        "declared_reads": [],
                        "deploying_workflows": [".github/workflows/auto-tag.yml", ".github/workflows/deploy*.yml"] if workflows is None else workflows}
        write(repo / "config/quality.json", json.dumps(q))
        write(repo / ".github/workflows/auto-tag.yml", "on: push\njobs:\n  t:\n    steps:\n      - run: |\n          bash ./scripts/release.sh\n          cat docs/old.md   # a comment: docs/legacy/x.md\n          echo \"issue #12 docs/setup.md\"\n          python3 scripts/gate.py runtime-surface\n          cat ../outside.json\n")
        write(repo / "scripts/release.sh", "#!/bin/bash\nbash \"$ROOT/scripts/version.sh\"\ncat config/quality.json\necho https://example.com/a/b refs/heads/main origin/main /tmp/x\n")
        write(repo / "scripts/version.sh", "cat docs/legacy/x.md\n")
        write(repo / ".github/workflows/governance-check.yml", "run: cat docs/never.md\n")   # not a deploying workflow: never scanned
        write(repo / "docs/never.md", "n\n"); write(repo / "outside.json", "{}")
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "deploy files"], check=True)
        subprocess.run(["git", "-C", str(repo), "branch", "-M", "main"], check=True)
        subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/main", "HEAD"], check=True)
        return repo

    def _commit(self, repo, msg):
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", msg], check=True)

    def test_changed_is_positive_and_fails_closed(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            write(repo / "docs/notes.md", "n\n"); self._commit(repo, "docs")
            c = runtime.changed(repo, "origin/main")
            self.assertFalse(c["touched"]); self.assertIn("branch and pull request", c["reason"])
            write(repo / "src/app.py", "print(2)\n"); self._commit(repo, "code")
            c = runtime.changed(repo, "origin/main")
            self.assertTrue(c["touched"]); self.assertEqual(c["hits"], ["src/app.py"])
            subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/main", "HEAD"], check=True)
            write(repo / ".github/workflows/auto-tag.yml", "on: push\n"); self._commit(repo, "wf")
            c = runtime.changed(repo, "origin/main")
            self.assertTrue(c["touched"]); self.assertEqual(c["always"], [".github/workflows/auto-tag.yml"], "a hard exclusion fires regardless")
            self.assertTrue(runtime.changed(repo, "HEAD^1")["touched"], "HEAD^1 — the merge's first parent — is the fallback CI shape")
            subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/main", "HEAD"], check=True)
            subprocess.run(["git", "-C", str(repo), "mv", "src/app.py", "docs/app.py"], check=True); self._commit(repo, "rename out")
            c = runtime.changed(repo, "origin/main")
            self.assertTrue(c["touched"]); self.assertIn("src/app.py", c["hits"], "a rename out of the surface removes a runtime file: seen from both sides")
            subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/main", "HEAD"], check=True)
            write(repo / "src/café.py", "1\n"); self._commit(repo, "non-ascii")
            self.assertTrue(runtime.changed(repo, "origin/main")["touched"], "a non-ASCII path on the surface is read unquoted")
            q = json.loads((repo / "config/quality.json").read_text()); q["surface"]["runtime_surface"] = []
            write(repo / "config/quality.json", json.dumps(q))
            c = runtime.changed(repo, "origin/main")
            self.assertTrue(c["touched"]); self.assertIn("no runtime surface declared", c["reason"], "an empty list deploys everything, said")
            q["surface"]["runtime_surface"] = "src/**"; write(repo / "config/quality.json", json.dumps(q))
            with self.assertRaisesRegex(GateFault, "must be a list"):
                runtime.changed(repo, "origin/main")
            q["surface"]["runtime_surface"] = ["src/**"]; q["surface"]["declared_reads"] = [{"path": "x"}]; write(repo / "config/quality.json", json.dumps(q))
            with self.assertRaisesRegex(GateFault, "names its reason"):
                runtime.changed(repo, "origin/main")

    def test_parity_holds_the_list_to_what_the_jobs_read(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            f, stats = runtime.parity(repo)
            self.assertEqual(stats["workflows"], [".github/workflows/auto-tag.yml"], "only the declared deploying workflows are scanned")
            by = {x["path"]: x["reason"] for x in f}
            self.assertEqual(set(by), {"docs/old.md", "docs/setup.md", "docs/legacy/x.md"},
                             "the workflow's own read, a read after a quoted #, and one two scripts deep via ./ and $ROOT/ calls")
            self.assertIn(".github/workflows/auto-tag.yml", by["docs/old.md"]); self.assertIn("scripts/version.sh", by["docs/legacy/x.md"])
            self.assertNotIn("docs/never.md", by, "a non-deploying workflow is not scanned"); self.assertNotIn("outside.json", by, "../ escapes the tree")
            self.assertNotIn("scripts/gate.py", " ".join(by), "the gate reader is not a deploy read")
            q = json.loads((repo / "config/quality.json").read_text())
            q["surface"]["declared_reads"] = [{"path": "docs/old.md", "reason": "release notes source"}, {"path": "docs/**", "reason": "docs are read"}, {"path": "docs/gone.md", "reason": "old"}]
            write(repo / "config/quality.json", json.dumps(q))
            f, _ = runtime.parity(repo)
            self.assertEqual([x["path"] for x in f], ["docs/gone.md"], "a glob declared read covers; an exact one too; a path nothing reads is stale"); self.assertIn("stale exemption", f[0]["reason"])
            q["surface"]["declared_reads"] = []; q["surface"]["runtime_surface"] = ["src/**", "scripts/**", "docs/**"]
            write(repo / "config/quality.json", json.dumps(q))
            self.assertEqual(runtime.parity(repo)[0], [], "widening the surface covers the reads")
            q["surface"]["runtime_surface"] = []; write(repo / "config/quality.json", json.dumps(q))
            self.assertTrue(any("is empty" in x["reason"] for x in runtime.parity(repo)[0]), "an undeclared surface is a finding, not a silent deploy-everything")
            q["surface"]["runtime_surface"] = ["src/**", "scripts/**"]; q["surface"]["deploying_workflows"] = [".gitlab-ci-auto-tag.yml", "Jenkinsfile*"]
            write(repo / "config/quality.json", json.dumps(q))
            f, stats = runtime.parity(repo)
            self.assertEqual(stats["workflows"], []); self.assertTrue(any("no deploying workflow found" in x["reason"] for x in f), "a platform whose files never land is red, never a vacuous green")
            write(repo / ".gitlab-ci-auto-tag.yml", "script:\n  - bash scripts/release.sh\n"); write(repo / "Jenkinsfile.auto-tag", "// see docs/setup.md\nsh 'cat docs/j.md'\n"); write(repo / "docs/j.md", "j\n")
            self._commit(repo, "platform files")
            f, stats = runtime.parity(repo)
            self.assertEqual(stats["workflows"], [".gitlab-ci-auto-tag.yml", "Jenkinsfile.auto-tag"], "root-level platform files are found through the key")
            by = {x["path"]: x["reason"] for x in f}
            self.assertIn("docs/j.md", by, "a groovy read"); self.assertIn("docs/legacy/x.md", by, "the transitive read through the gitlab file")
            self.assertNotIn("Jenkinsfile.auto-tag", by.get("docs/setup.md", ""), "a groovy // comment is not a read (the path is read elsewhere, by the gitlab file's scripts)")


class Planning(unittest.TestCase):
    """EVOL-048: one planning stage — governed precedence, classes fail closed, the marker only from the harness, adoption once."""

    PLAN = {"governed_paths": ["src/**", "config/**", ".claude/**"],
            "gate_inputs": ["docs/constitution.md", "config/**", ".claude/**"],
            "exempt_classes": ["feature", "increment", "train", "sub-increment", "epic"], "plan_artefact": None, "adoption_window_minutes": 30, "approval_ttl_hours": 168}
    DOCS = {"paths": ["**/*.md", "docs/**"], "exclusions": [".github/workflows/**"]}

    def _repo(self, tmp, plan=None):
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text()); q["planning"] = plan or dict(self.PLAN); q["documentation"] = dict(self.DOCS)
        write(repo / "config/quality.json", json.dumps(q))
        write(repo / "src/docs/gen.py", "x\n")
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "plan cfg"], check=True)
        subprocess.run(["git", "-C", str(repo), "branch", "-M", "main"], check=True)
        subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/main", "HEAD"], check=True)
        write(repo / "transcript.jsonl", '{"type":"assistant","message":{"content":[{"type":"tool_use","id":"toolu_ok","name":"ExitPlanMode","input":{}}]}}\n')
        return repo

    def _payload(self, repo, **kw):
        return {"hook_event_name": "PostToolUse", "tool_name": "ExitPlanMode", "session_id": "s1", "transcript_path": str(repo / "transcript.jsonl"), "tool_use_id": "toolu_ok", **kw}

    def _on(self, repo, b):
        subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-B", b], check=True)

    def test_governed_precedence(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            self.assertEqual(planning.governed(repo, "src/app.py")[0], True)
            self.assertEqual(planning.governed(repo, "docs/notes.md")[0], False, "documentation is exempt")
            self.assertEqual(planning.governed(repo, "README.md")[0], False)
            self.assertEqual(planning.governed(repo, "docs/constitution.md"), (True, "an input of a gate — governed like code whatever its extension"))
            self.assertEqual(planning.governed(repo, ".claude/rules/python.md")[0], True, "a rule is a gate input even as .md")
            self.assertEqual(planning.governed(repo, ".claude/skills/factory-rdr/SKILL.md")[0], True, "a skill is a behavioural contract, never documentation")
            self.assertEqual(planning.governed(repo, "src/docs/gen.py")[0], True, "docs/** is root-anchored: code under a docs/ folder is code")
            self.assertEqual(planning.governed(repo, "assets/logo.png")[0], False)
            self.assertEqual(planning.governed(repo, str(repo / "src/x.py"))[0], True, "absolute paths inside the repo are relativised")
            self.assertEqual(planning.governed(repo, "/outside/config/x.json"), (False, "outside the repository — not a governed write"))
            self.assertEqual(planning.governed(repo, "../sibling/src/x.py")[0], False)
            q = json.loads((repo / "config/quality.json").read_text()); del q["planning"]; write(repo / "config/quality.json", json.dumps(q))
            with self.assertRaisesRegex(GateFault, "`planning` is missing"):
                planning.governed(repo, "src/app.py")
            g = planning.gate(repo, "config/quality.json", "fix/x")
            self.assertFalse(g["block"]); self.assertIn("may add it", g["reason"], "the one write that can add the missing block passes")
            with self.assertRaisesRegex(GateFault, "`planning` is missing"):
                planning.gate(repo, "src/app.py", "fix/x")
            st = planning.status(repo, "fix/x"); self.assertTrue(st["warn"]); self.assertIn("will be BLOCKED", st["line"], "the advisory never faults")

    def test_meta_config_governs_the_framework_product(self):
        real = HERE.parent.parent
        if not (real / "config/quality.json").is_file() or not (real / ".context/templates/setup").is_dir():
            self.skipTest("not the framework repo")
        for rel in (".claude/skills/factory-rdr/SKILL.md", ".claude/instructions/Factory-protocol-iop-intent-map.instructions.md", ".claude/commands/implement.md",
                    ".context/templates/setup/claude/CLAUDE.md", ".context/templates/architect/increment_plan_template.md", "config/quality.json", "scripts/gate.py", ".github/workflows/governance-check.yml"):
            self.assertEqual(planning.governed(real, rel)[0], True, f"{rel}: the framework's product is a gate input, never documentation")
        for rel in ("docs/project_log/evolutions/ADR-EVOL-048.md", "README.md", "docs/constitution.md"):
            self.assertEqual(planning.governed(real, rel)[0], False, f"{rel}: documentation — the plan artefact itself is never a gate input")
        self.assertEqual(planning._cfg(real)["exempt_classes"], [], "no class is exempt in the framework repo")

    def test_classes_fail_closed_and_the_marker_comes_only_from_the_harness(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            self._on(repo, "feature/F-001-login")
            self.assertEqual(planning.approval(repo)["source"], "phase", "a feature is planned by the framework's phases")
            with self.assertRaisesRegex(GateFault, "second receipt"):
                planning.record(repo, self._payload(repo))
            self.assertTrue(planning.enter(repo)["block"], "plan mode on a phase-planned class is a second stage")
            self._on(repo, "fix/x")
            self.assertFalse(planning.enter(repo)["block"], "a fix has no phase: plan mode is its one stage")
            a = planning.approval(repo)
            self.assertFalse(a["approved"]); self.assertIn("no framework planning phase and no approved plan", a["reason"])
            g = planning.gate(repo, "src/app.py")
            self.assertTrue(g["block"]); self.assertIn("plan mode", g["resolution"])
            self.assertFalse(planning.gate(repo, "docs/x.md")["block"], "a documentation write on a gated class passes")
            self.assertTrue(planning.gate(repo, "docs/constitution.md")["block"], "a gate input on a gated class blocks")
            for bad, why in (({"hook_event_name": "PostToolUse", "tool_name": "Edit"}, "only from the harness"),
                             ({"tool_name": "ExitPlanMode"}, "only from the harness"),
                             (self._payload(repo, permission_mode="bypassPermissions"), "no human ratified"),
                             (self._payload(repo, transcript_path=str(repo / "nope.jsonl")), "transcript_path"),
                             (self._payload(repo, tool_use_id="toolu_other"), "not this session's approval")):
                with self.assertRaisesRegex(GateFault, why):
                    planning.record(repo, bad)
            self.assertFalse(planning.marker_path(repo, "fix/x").exists(), "nothing written by a refused payload")
            m = planning.record(repo, self._payload(repo, permission_mode="default", cwd="/w"))
            self.assertEqual((m["branch"], m["permission_mode"], m["tool_use_id"]), ("fix/x", "default", "toolu_ok")); self.assertTrue(planning.marker_path(repo, "fix/x").is_file())
            a = planning.approval(repo)
            self.assertTrue(a["approved"]); self.assertEqual(a["source"], "harness:ExitPlanMode")
            self.assertFalse(planning.gate(repo, "src/app.py")["block"])
            # the own marker names its branch (no slug collision) and expires with the TTL
            self._on(repo, "fix-x")
            self.assertFalse(planning.approval(repo)["approved"], "fix-x does not inherit fix/x's marker through the slug")
            self._on(repo, "fix/x")
            old = json.loads(planning.marker_path(repo, "fix/x").read_text()); old["approved_at"] = "2020-01-01T00:00:00Z"
            planning.marker_path(repo, "fix/x").write_text(json.dumps(old))
            a = planning.approval(repo); self.assertFalse(a["approved"]); self.assertIn("older than planning.approval_ttl_hours", a["reason"])
            old["approved_at"] = "2099-01-01T00:00:00Z"; planning.marker_path(repo, "fix/x").write_text(json.dumps(old))
            a = planning.approval(repo); self.assertFalse(a["approved"]); self.assertIn("future timestamp", a["reason"])
            planning.marker_path(repo, "fix/x").unlink()
            for b in ("chore/x", "docs/x", "breaking/x", "weird"):
                self._on(repo, b)
                self.assertFalse(planning.approval(repo)["approved"], f"{b}: an unlisted class is gated")
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "main"], check=True)
            self.assertFalse(planning.approval(repo)["approved"], "main: gated")
            st = planning.status(repo, "chore/x")
            self.assertTrue(st["warn"]); self.assertIn("BLOCKED", st["line"])
            self.assertFalse(planning.status(repo, "feature/F-001-login")["warn"])
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "--detach"], check=True)
            st = planning.status(repo); self.assertTrue(st["warn"]); self.assertIn("detached HEAD", st["line"], "the advisory says it even on a detached HEAD")
            with self.assertRaisesRegex(GateFault, "check out the branch"):
                planning.record(repo, self._payload(repo))

    def test_adoption_once_within_the_window_and_the_plan_artefact(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "main"], check=True)
            planning.record(repo, self._payload(repo))   # approved on main, before the branch is cut
            self._on(repo, "fix/one")
            a = planning.approval(repo)
            self.assertTrue(a["approved"]); self.assertEqual(a["source"], "adopted"); self.assertIn("adopted by this branch", a["reason"])
            own = json.loads(planning.marker_path(repo, "fix/one").read_text()); self.assertIsNone(own["adopted_by"]); self.assertEqual(own["branch"], "fix/one")
            self.assertTrue(planning.approval(repo)["approved"], "the adopting branch keeps its own marker")
            self._on(repo, "fix/two")
            self.assertFalse(planning.approval(repo)["approved"], "single use: a second branch cannot adopt the same approval")
            planning.record(repo, self._payload(repo), branch="fix/one")   # a fresh, unadopted approval on another WORKING branch
            self.assertFalse(planning.approval(repo)["approved"], "another working branch's own marker is never adopted — only a base branch's")
            self.assertEqual(json.loads(planning.marker_path(repo, "main").read_text())["adopted_by"], "fix/one")
            planning.record(repo, self._payload(repo), branch="main")   # a fresh approval on main
            st = planning.status(repo); self.assertFalse(st["warn"]); self.assertIn("will be adopted", st["line"])
            self.assertIsNone(json.loads(planning.marker_path(repo, "main").read_text())["adopted_by"], "the advisory never consumes the adoption")
            planning.record(repo, self._payload(repo), branch="develop")   # two base approvals: the branch's own base wins
            self.assertIn("main", planning.approval(repo)["reason"]); self.assertEqual(json.loads(planning.marker_path(repo, "main").read_text())["adopted_by"], "fix/two")
            planning.marker_path(repo, "develop").unlink()   # the other base's approval stays adoptable by design; out of this test's way
            old = {"branch": "main", "approved_at": "2020-01-01T00:00:00Z", "source": "harness:ExitPlanMode", "adopted_by": None}
            planning.marker_path(repo, "main").write_text(json.dumps(old))
            self._on(repo, "fix/three")
            a = planning.approval(repo)
            self.assertFalse(a["approved"]); self.assertIn("outside the 30-minute adoption window", a["reason"], "an expired approval is said, never used")
            planning.marker_path(repo, "main").write_text(json.dumps({**old, "approved_at": "2026-09-25T10:00:00"}))   # naive: UTC, never a crash
            self.assertFalse(planning.approval(repo)["approved"])
            planning.marker_path(repo, "main").write_text(json.dumps({**old, "approved_at": "2099-01-01T00:00:00Z"}))
            self.assertFalse(planning.approval(repo)["approved"], "a future-dated approval is clock skew, never adopted")
            planning.marker_path(repo, "fix/three").write_text("{not json"); self.assertFalse(planning.approval(repo)["approved"], "an unreadable marker is no approval")
            # the branch's own plan artefact in an approved state — new or changed on the branch
            plan = dict(self.PLAN); plan["exempt_classes"] = []; plan["plan_artefact"] = "docs/project_log/evolutions/ADR-{ID}.md"
            q = json.loads((repo / "config/quality.json").read_text()); q["planning"] = plan; write(repo / "config/quality.json", json.dumps(q))
            self._on(repo, "feature/EVOL-099-x")
            a = planning.approval(repo); self.assertFalse(a["approved"]); self.assertIn("does not exist", a["reason"])
            write(repo / "docs/project_log/evolutions/ADR-EVOL-099.md", "---\nid: ADR-EVOL-099\nstatus: proposed\n---\n")
            a = planning.approval(repo); self.assertFalse(a["approved"]); self.assertIn("not an approved state", a["reason"])
            write(repo / "docs/project_log/evolutions/ADR-EVOL-099.md", "---\nid: ADR-EVOL-099\nstatus: accepted\n---\n")
            a = planning.approval(repo); self.assertTrue(a["approved"]); self.assertEqual(a["source"], "artefact")
            self.assertFalse(planning.approval(repo, "feature/EVOL-098-y")["approved"], "another evolution's ADR does not cover this branch")
            subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
            subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "adr"], check=True)
            subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/main", "HEAD"], check=True)   # the ADR ships to main
            self._on(repo, "fix/EVOL-099-typo")
            a = planning.approval(repo); self.assertFalse(a["approved"]); self.assertIn("already on main unchanged", a["reason"], "a shipped ADR is another change's plan")


RULE_AGENTS = """---
description: agents
applicable_when:
  always: true
agents:
  classes:
    phase: {family: writer, effort: medium, budget_bytes: 8000, tools: {must: [Read, Edit, Write, Bash], never: [Agent]}}
    worker: {family: writer, effort: medium, budget_bytes: 6000, tools: {must: [Read, Edit, Write, Bash], never: [Agent]}}
    plan-critic: {family: critic, effort: high, budget_bytes: 8000, tools: {must: [Read, Grep, Glob], never: [Edit, Write, NotebookEdit, Bash, Agent]}}
    work-critic: {family: critic, effort: high, budget_bytes: 4000, tools: {must: [Read, Grep, Glob], never: [Edit, Write, NotebookEdit, Bash, Agent]}}
    reader: {family: critic, effort: high, budget_bytes: 6000, tools: {must: [Read, Grep, Glob, WebFetch], allow_mcp: docs_mcp_allowlist, never: [Edit, Write, NotebookEdit, Bash, Agent]}}
  tiers: {small: {files: 5, lines: 150}, large: {files: 30, lines: 800}}
  resolve:
    - {class: worker, tier: small, effort: low}
    - {class: plan-critic, round: 2, effort: max}
  ladder: {critic: [writer], writer: []}
  rounds: {plan_gate: 2, work: 1}
  roster:
    - {name: factory-dev-backend, class: worker, surface: ["src/**"]}
    - {name: factory-plan-critic, class: plan-critic, surface: ["docs/**"]}
    - {name: factory-critic-security, class: work-critic, lens: security, surface: ["**"]}
    - {name: factory-docs-reader, class: reader, surface: ["package.json"]}
  spawn_sites:
    - {path: ".claude/commands/implement.md", policy: phase}
    - {path: ".claude/instructions/Factory-implement-build.instructions.md", policy: worker}
    - {path: ".claude/instructions/Factory-blueprint-design.instructions.md", policy: plan-critic}
    - {path: ".claude/skills/factory-code-review/SKILL.md", policy: work-critic}
    - {path: ".claude/instructions/Factory-implement-plan.instructions.md", policy: reader}
---
# agents
"""
READER_TOOLS = "Read, Grep, Glob, WebFetch, mcp__context7__query-docs, mcp__aws-knowledge__aws___read_documentation"
DOCS_SCAN = "---\nname: factory-mcp-docs-scan\ndocs_mcp_allowlist:\n  - context7\n  - aws-knowledge\n---\n"


def agent_def(name, cls, tools, extra="", body=""):
    return f"---\nname: {name}\ndescription: x\ntools: {tools}\neffort: high\nclass: {cls}\n{extra}---\n\n# {name}\n{body}\n"


class Agents(unittest.TestCase):
    """EVOL-049: the class policy and the roster — validated, resolved per spawn, digested, contracts checked; red first."""

    def _repo(self, tmp, writer="sonnet", critic="opus"):
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text()); q["agents"] = {"families": {"writer": writer, "critic": critic}}
        write(repo / "config/quality.json", json.dumps(q))
        write(repo / ".claude/rules/agents.md", RULE_AGENTS)
        write(repo / ".claude/agents/factory-dev-backend.md", agent_def("factory-dev-backend", "worker", "Read, Edit, Write, Bash", body="see `rules/testing.md`"))
        write(repo / ".claude/agents/factory-plan-critic.md", agent_def("factory-plan-critic", "plan-critic", "Read, Grep, Glob"))
        write(repo / ".claude/agents/factory-critic-security.md", agent_def("factory-critic-security", "work-critic", "Read, Grep, Glob"))
        write(repo / ".claude/agents/factory-docs-reader.md", agent_def("factory-docs-reader", "reader", READER_TOOLS))
        write(repo / ".claude/skills/factory-mcp-docs-scan/SKILL.md", DOCS_SCAN)
        write(repo / ".claude/instructions/Factory-implement-plan.instructions.md", "---\ndescription: p\n---\nspawn-policy: reader\n")
        write(repo / ".claude/rules/testing.md", "---\ndescription: t\n---\n")
        write(repo / ".claude/instructions/Factory-implement-build.instructions.md", "---\ndescription: b\napplicable_when:\n  phase: [IMPLEMENT]\n---\nspawn-policy: worker\n")
        write(repo / ".claude/instructions/Factory-blueprint-design.instructions.md", "---\ndescription: d\n---\nspawn-policy: plan-critic\n")
        write(repo / ".claude/skills/factory-code-review/SKILL.md", "---\nname: cr\n---\nspawn-policy: work-critic\n")
        write(repo / ".claude/commands/implement.md", "---\ndescription: i\n---\nspawn-policy: phase\n")
        self.manifest = {"templates": {f"claude/agents/{n}.md": {"version": "1.0.0"} for n in ("factory-dev-backend", "factory-plan-critic", "factory-critic-security", "factory-docs-reader")}}
        return repo

    def test_policy_and_validator_green_then_red(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            pol = agents.policy(repo)
            self.assertEqual(set(pol["classes"]), {"phase", "worker", "plan-critic", "work-critic", "reader"}); self.assertEqual(pol["families"], {"writer": "sonnet", "critic": "opus"})
            self.assertEqual(agents.validate(repo, self.manifest), [], "the fixture roster is green")
            # same family
            q = json.loads((repo / "config/quality.json").read_text()); q["agents"]["families"]["critic"] = "sonnet"; write(repo / "config/quality.json", json.dumps(q))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("same alias" in x["reason"] for x in f), "critic on the writer's family is refused")
            q["agents"]["families"]["critic"] = "opus"; write(repo / "config/quality.json", json.dumps(q))
            # a critic with a write tool; a worker without one; model written in; no effort; over budget; dangling pointer
            write(repo / ".claude/agents/factory-critic-security.md", agent_def("factory-critic-security", "work-critic", "Read, Grep, Glob, Edit"))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("Edit is not read-only" in x["reason"] for x in f))
            # the critic allowlist: a permission-pattern spelling, a case variant, an mcp mutator, the old Task name — none slips through
            for spelled in ("Bash(git diff:*)", "bash", "mcp__filesystem__write_file", "Task", "Write(*)"):
                write(repo / ".claude/agents/factory-critic-security.md", agent_def("factory-critic-security", "work-critic", f"Read, Grep, Glob, {spelled}"))
                f = agents.validate(repo, self.manifest); self.assertTrue(any(f"{spelled} is not read-only" in x["reason"] for x in f), spelled)
            # the roster class is the class: a definition promoting itself to a writer is red
            write(repo / ".claude/agents/factory-critic-security.md", agent_def("factory-critic-security", "worker", "Read, Grep, Glob, Edit, Write, Bash"))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("the roster says `work-critic`" in x["reason"] for x in f), "a definition never promotes itself")
            self.assertTrue(any("is not read-only" in x["reason"] for x in f), "and it is still held to the roster class's matrix")
            # name ≠ file, no description
            write(repo / ".claude/agents/factory-critic-security.md", agent_def("factory-critic-securty", "work-critic", "Read, Grep, Glob").replace("description: x", "description:"))
            f = agents.validate(repo, self.manifest)
            self.assertTrue(any("is not the file name" in x["reason"] for x in f)); self.assertTrue(any("no `description`" in x["reason"] for x in f))
            write(repo / ".claude/agents/factory-critic-security.md", agent_def("factory-critic-security", "work-critic", "Read, Grep, Glob", extra="model: opus\n", body="x" * 5000))
            f = agents.validate(repo, self.manifest)
            self.assertTrue(any("`model` written into the definition" in x["reason"] for x in f)); self.assertTrue(any("over the class budget" in x["reason"] for x in f))
            write(repo / ".claude/agents/factory-critic-security.md", agent_def("factory-critic-security", "work-critic", "Read, Grep, Glob").replace("effort: high\n", ""))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("`effort: (none)`" in x["reason"] for x in f))
            write(repo / ".claude/agents/factory-critic-security.md", agent_def("factory-critic-security", "work-critic", "Read, Grep, Glob"))
            write(repo / ".claude/agents/factory-dev-backend.md", agent_def("factory-dev-backend", "worker", "Read, Bash", body="see `rules/nope.md`"))
            f = agents.validate(repo, self.manifest)
            self.assertTrue(any("must have Edit, Write" in x["reason"] for x in f)); self.assertTrue(any("resolves to nothing" in x["reason"] for x in f))
            write(repo / ".claude/agents/factory-dev-backend.md", agent_def("factory-dev-backend", "worker", "Read, Edit, Write, Bash"))
            # roster parity: an unlisted definition; a roster name without a file; a file without a manifest entry
            write(repo / ".claude/agents/rogue.md", agent_def("rogue", "worker", "Read, Edit, Write, Bash"))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("the roster does not name" in x["reason"] for x in f))
            (repo / ".claude/agents/rogue.md").unlink()
            (repo / ".claude/agents/factory-plan-critic.md").unlink()
            f = agents.validate(repo, self.manifest); self.assertTrue(any("no agent definition exists" in x["reason"] for x in f))
            write(repo / ".claude/agents/factory-plan-critic.md", agent_def("factory-plan-critic", "plan-critic", "Read, Grep, Glob"))
            f = agents.validate(repo, {"templates": {}}); self.assertEqual(sum("no manifest entry" in x["reason"] for x in f), 4, "undelivered definitions are red")
            # families: a placeholder, `inherit`, a case variant of the same alias
            for w, c, needle in (("{{AGENT_WRITER_MODEL}}", "opus", "placeholder"), ("sonnet", "inherit", "placeholder"), ("Opus", "opus", "same alias")):
                q = json.loads((repo / "config/quality.json").read_text()); q["agents"]["families"] = {"writer": w, "critic": c}; write(repo / "config/quality.json", json.dumps(q))
                f = agents.validate(repo, self.manifest); self.assertTrue(any(needle in x["reason"] for x in f), (w, c))
            q["agents"]["families"] = {"writer": "sonnet", "critic": "opus"}; write(repo / "config/quality.json", json.dumps(q))
            # class policy: an unknown family; a family the tools contradict; a dead resolve row; a bad cap
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace("work-critic: {family: critic", "work-critic: {family: reader"))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("is not one of critic, writer" in x["reason"] for x in f))
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace("work-critic: {family: critic", "work-critic: {family: writer"))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("a read-only class is a critic" in x["reason"] for x in f))
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace("- {class: worker, tier: small, effort: low}", "- {class: worker, tier: small, effort: medium}\n    - {class: sorcerer, effort: low}\n    - {class: worker, tier: gigantic, effort: low}"))
            f = agents.validate(repo, self.manifest)
            self.assertTrue(any("restates the class default" in x["reason"] for x in f), "a row that changes nothing is dead data")
            self.assertTrue(any("names no known class" in x["reason"] for x in f)); self.assertTrue(any("tier `gigantic`" in x["reason"] for x in f))
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace("rounds: {plan_gate: 2, work: 1}", "rounds: {plan_gate: 2}"))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("agents.rounds.work" in x["reason"] for x in f), "the cap is a key, present")
            # the vendored engine lenses are held to the critic matrix and the budget
            write(repo / ".claude/skills/factory-code-review/agents/code-reviewer.md", agent_def("code-reviewer", "work-critic", "Read, Grep, Glob, Bash"))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("agents/code-reviewer.md" in x["path"] and "Bash is not read-only" in x["reason"] for x in f), "a vendored lens cannot carry a write tool")
            write(repo / ".claude/skills/factory-code-review/agents/code-reviewer.md", agent_def("code-reviewer", "worker", "Read, Edit"))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("a vendored lens is a prompt for a read-only critic class" in x["reason"] for x in f))
            (repo / ".claude/skills/factory-code-review/agents/code-reviewer.md").unlink()
            # ladder and spawn sites
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace("ladder: {critic: [writer], writer: []}", "ladder: {critic: [writer], writer: [critic]}"))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("never degrades" in x["reason"] for x in f))
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace("ladder: {critic: [writer], writer: []}", "ladder: {opus: [sonnet]}"))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("is not a family" in x["reason"] for x in f), "the ladder is keyed by families, never by ids")
            write(repo / ".claude/rules/agents.md", RULE_AGENTS)
            write(repo / ".claude/skills/factory-code-review/SKILL.md", "---\nname: cr\n---\nno marker\n")
            f = agents.validate(repo, self.manifest); self.assertTrue(any("does not declare `spawn-policy: work-critic`" in x["reason"] for x in f))
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace('    - {path: ".claude/skills/factory-code-review/SKILL.md", policy: work-critic}\n', ""))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("has no spawn site" in x["reason"] for x in f), "a policy nobody spawns is dead data")
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace('    - {path: ".claude/commands/implement.md", policy: phase}\n', ""))
            f = agents.validate(repo, self.manifest); self.assertTrue(any("class `phase` has no spawn site" in x["reason"] for x in f), "the phase class is spawned too — by the commands")
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace("agents:\n  classes:", "agents:\n  classes_x:"))
            with self.assertRaisesRegex(GateFault, "agents.classes"):
                agents.policy(repo)

    def test_resolve_fallback_digest_and_return_contracts(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            r = agents.resolve(repo, "work-critic", surface="Security", files=2, lines=10)
            self.assertEqual((r["model"], r["family"], r["effort"], r["matched"]), ("opus", "critic", "high", "class default"), "critics run at the class default on every lens")
            r = agents.resolve(repo, "worker", surface="backend", files=2, lines=10)
            self.assertEqual((r["model"], r["effort"], r["tier"]), ("sonnet", "low", "small"), "a small diff steps the effort down")
            r = agents.resolve(repo, "worker", files=40, lines=2000)
            self.assertEqual((r["effort"], r["tier"]), ("medium", "large"), "no row for a large worker diff: the class default")
            r = agents.resolve(repo, "worker")
            self.assertEqual((r["effort"], r["tier"], r["matched"]), ("medium", "unknown", "class default"), "a size nobody measured is unknown, never small")
            self.assertEqual(agents.resolve(repo, "plan-critic", round_=1)["matched"], "class default")
            self.assertEqual((agents.resolve(repo, "plan-critic", round_=2)["effort"], agents.resolve(repo, "plan-critic", round_=2)["matched"]), ("max", "round: 2, effort: max"), "the second round steps up by its row")
            r = agents.resolve(repo, "plan-critic", round_=3); self.assertFalse(r["ok"]); self.assertIn("over the cap 2", r["reason"])
            r = agents.resolve(repo, "work-critic", round_=2); self.assertFalse(r["ok"]); self.assertIn("agents.rounds.work", r["reason"], "one work round — the cap is enforced by the resolver, not by prose")
            self.assertTrue(agents.resolve(repo, "worker", round_=9)["ok"], "writers have no round cap")
            with self.assertRaisesRegex(GateFault, "not one of"):
                agents.resolve(repo, "sorcerer")
            f = agents.fallback(repo, "worker", "writer"); self.assertFalse(f["ok"]); self.assertIn("never degrades", f["reason"])
            f = agents.fallback(repo, "work-critic", "critic"); self.assertTrue(f["ok"]); self.assertEqual(f["model"], "sonnet")
            self.assertFalse(f["separation"], "the only other family is the writer's: the reader says the separation is lost"); self.assertIn("adjudication", f["reason"])
            f = agents.fallback(repo, "work-critic", "writer"); self.assertFalse(f["ok"])
            f = agents.fallback(repo, "work-critic", "reader"); self.assertFalse(f["ok"]); self.assertIn("is not a family", f["reason"])
            # digest: the roster surface expanded over the tracked tree — a path-bound rule of the lens lands; always-on rules too
            write(repo / ".claude/rules/security.md", "---\ndescription: s\napplicable_when:\n  path_glob: [\"src/**\"]\n---\n")
            write(repo / ".claude/rules/always.md", "---\ndescription: a\napplicable_when:\n  always: true\n---\n")
            subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True, capture_output=True)
            text, fp, budget = agents.digest(repo, "factory-critic-security")
            self.assertIn("security.md", text, "a `**` surface reaches the path-bound rules of the tree, not the literal `**`")
            self.assertIn("always.md", text, "a spawned agent gets no snapshot: the always-on rules ride in the digest")
            self.assertIn('paths="**"', text, "the head names the surface, never the file list")
            text, fp, budget = agents.digest(repo, "factory-dev-backend")
            self.assertLessEqual(len(text.encode()), budget); self.assertEqual(budget, 6000); self.assertTrue(fp); self.assertIn("security.md", text)
            with self.assertRaisesRegex(GateFault, "not in the roster"):
                agents.digest(repo, "nobody")
            # spawn: a roster agent on its family's alias; not ours otherwise
            self.assertTrue(agents.spawn_check(repo, "factory-critic-security", "opus")["ok"])
            self.assertTrue(agents.spawn_check(repo, "factory-critic-security", "Opus")["ok"], "aliases compare case-folded")
            r = agents.spawn_check(repo, "factory-critic-security", "sonnet"); self.assertFalse(r["ok"]); self.assertEqual(r["expected"], "opus")
            r = agents.spawn_check(repo, "factory-dev-backend", ""); self.assertFalse(r["ok"]); self.assertIn("without a model", r["reason"])
            self.assertTrue(agents.spawn_check(repo, "general-purpose", "")["ok"], "a type outside the roster is not governed")
            worker_ok = "did x\n## Governance\nRules read: testing.md\nLaws applied: LAW-05\nDefect classes: DC-01\nSources: src/a.py:1\n"
            self.assertEqual(agents.check_return(worker_ok, "worker"), [])
            self.assertTrue(agents.check_return("did x", "worker"), "a worker without its governance block is refused")
            gov = "## Governance\nRules read: x\nLaws applied: y\nDefect classes: z\nSources: s\n"
            critic_ok = "src/a.py:12 · 🔴 · confidence 90% · probe: ran pytest -k a\n" + gov
            self.assertEqual(agents.check_return(critic_ok, "work-critic"), [])
            self.assertEqual(agents.check_return("- **src/a.py:12** · 🟡 · confidence 80% · probe: read the handler\n" + gov, "work-critic"), [], "a bulleted, bolded finding is in shape")
            bad = "src/a.py:12 · 🔴 · confidence 90%\n" + gov
            self.assertTrue(any("outside the contract shape" in p for p in agents.check_return(bad, "work-critic")), "a finding without an executed probe is refused")
            for fake in ("n/a", "none", "—", "-", "tbd"):
                self.assertTrue(any("without an executed probe" in p for p in agents.check_return(f"src/a.py:12 · 🔴 · confidence 90% · probe: {fake}\n" + gov, "work-critic")), fake)
            mixed = critic_ok.replace(gov, "") + "- src/b.py:3 · 🔴 · confidence 90%\n" + gov
            self.assertTrue(any("src/b.py:3" in p for p in agents.check_return(mixed, "work-critic")), "every line carrying a severity is held to the shape, not only the first")
            self.assertEqual(agents.check_return("no findings\n" + gov, "work-critic"), [])
            self.assertTrue(agents.check_return("I found no findings of severity blocker but three majors.\n" + gov, "work-critic"), "`no findings` counts only as a whole line")
            with self.assertRaisesRegex(GateFault, "needs --class"):
                agents.check_return(critic_ok, "")


    def test_reader_class_docs_mcp_allowlist_and_return_contract(self):
        """EVOL-056: a read-only class may borrow the [LAW-10] allowlist — read operations of listed servers only; the reader's return has its sources, its answer, its unknowns."""
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            self.assertEqual(agents.validate(repo, self.manifest), [], "context7 / aws-knowledge read operations are admitted")
            def reader(tools):
                write(repo / ".claude/agents/factory-docs-reader.md", agent_def("factory-docs-reader", "reader", tools))
                return " | ".join(x["reason"] for x in agents.validate(repo, self.manifest) if x["path"].endswith("factory-docs-reader.md"))
            self.assertIn("not a read operation", reader(READER_TOOLS + ", mcp__aws-knowledge__aws___create_stack"), "a mutator on an allowlisted server is red")
            self.assertIn("not in the documentation allowlist", reader(READER_TOOLS + ", mcp__chrome-devtools__take_snapshot"), "a server outside [LAW-10]'s list is red")
            self.assertIn("not read-only", reader(READER_TOOLS + ", Bash(git log:*)"), "a write tool stays red whatever the allowlist")
            for ok in ("mcp__pulumi__pulumi-registry-get-resource",):
                write(repo / ".claude/skills/factory-mcp-docs-scan/SKILL.md", DOCS_SCAN.replace("  - aws-knowledge\n", "  - aws-knowledge\n  - pulumi\n"))
                self.assertEqual(reader(READER_TOOLS + ", " + ok), "", ok)
            self.assertIn("not a read operation", reader(READER_TOOLS + ", mcp__pulumi__pulumi-cli-up"), "a deploy on an allowlisted server is red")
            # a mutator that carries a read token is still a mutator (two closed vocabularies); a nested server segment is not a tool; names are exact; personal-data connectors never
            for bad, why in (("mcp__context7__delete_by_query", "write verb"), ("mcp__pulumi__update-search-index", "write verb"), ("mcp__aws-knowledge__create_and_get_stack", "write verb"),
                             ("mcp__context7__evil__get_x", "nested"), ("mcp__Context7__query-docs", "not in the documentation allowlist"), ("mcp__aws_knowledge__aws___read_documentation", "not in the documentation allowlist")):
                self.assertIn(why, reader(READER_TOOLS + ", " + bad), bad)
            write(repo / ".claude/skills/factory-mcp-docs-scan/SKILL.md", DOCS_SCAN.replace("  - aws-knowledge\n", "  - aws-knowledge\n  - claude_ai_Google_Drive\n"))
            self.assertIn("personal-data connector", reader(READER_TOOLS + ", mcp__claude_ai_Google_Drive__read_file_content"), "a listed personal-data connector is still refused")
            write(repo / ".claude/skills/factory-mcp-docs-scan/SKILL.md", DOCS_SCAN)
            write(repo / ".claude/agents/factory-docs-reader.md", agent_def("factory-docs-reader", "reader", "").replace("tools: \n", "tools:\n"))
            self.assertTrue(any("must have" in x["reason"] for x in agents.validate(repo, self.manifest)), "`tools:` with no value is a finding (the must-list), never a traceback")
            write(repo / ".claude/agents/factory-docs-reader.md", agent_def("factory-docs-reader", "reader", READER_TOOLS))
            # a vendored lens may not borrow the reader class
            write(repo / ".claude/skills/factory-code-review/agents/lens.md", agent_def("lens", "reader", READER_TOOLS))
            self.assertTrue(any("without MCP tools" in x["reason"] for x in agents.validate(repo, self.manifest)))
            (repo / ".claude/skills/factory-code-review/agents/lens.md").unlink()
            (repo / ".claude/skills/factory-mcp-docs-scan/SKILL.md").unlink()
            self.assertIn("no documentation allowlist delivered", reader(READER_TOOLS), "no [LAW-10] list = no mcp tool admitted, said")
            write(repo / ".claude/skills/factory-mcp-docs-scan/SKILL.md", DOCS_SCAN); self.assertEqual(reader(READER_TOOLS), "")
            # allow_mcp belongs to read-only classes only; the value is the one list
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace("worker: {family: writer, effort: medium, budget_bytes: 6000, tools: {must: [Read, Edit, Write, Bash], never: [Agent]}}", "worker: {family: writer, effort: medium, budget_bytes: 6000, tools: {must: [Read, Edit, Write, Bash], allow_mcp: docs_mcp_allowlist, never: [Agent]}}"))
            with self.assertRaisesRegex(GateFault, "class that writes"):
                agents.policy(repo)
            write(repo / ".claude/rules/agents.md", RULE_AGENTS.replace("allow_mcp: docs_mcp_allowlist", "allow_mcp: anything"))
            with self.assertRaisesRegex(GateFault, "must be `docs_mcp_allowlist`"):
                agents.policy(repo)
            write(repo / ".claude/rules/agents.md", RULE_AGENTS)
            # the reader runs on the critic family: resolve and the spawn hook
            r = agents.resolve(repo, "reader"); self.assertEqual((r["family"], r["model"], r["effort"]), ("critic", "opus", "high"))
            self.assertFalse(agents.spawn_check(repo, "factory-docs-reader", "sonnet")["ok"]); self.assertTrue(agents.spawn_check(repo, "factory-docs-reader", "opus")["ok"])
            # the return contract
            gov = "## Governance\nRules read: rules/agents.md\nLaws applied: LAW-10\nDefect classes: none\nSources: 1\n"
            good = "## Sources\n- mcp · context7 · fastapi 0.115 lifespan · https://fastapi.tiangolo.com/advanced/events/ · lifespan replaces on_event since 0.93\n## Answer\nUse lifespan [1].\n## Unknowns\nnone\n" + gov
            self.assertEqual(agents.check_return(good, "reader"), [])
            self.assertEqual(agents.check_return("## Sources\nno sources\n## Answer\nknown-cold: nothing reachable\n## Unknowns\n- is lifespan async · searched: context7 fastapi, web\n" + gov, "reader"), [])
            self.assertTrue(any("no `## Sources`" in p for p in agents.check_return("## Answer\nx\n## Unknowns\nnone\n" + gov, "reader")))
            self.assertTrue(any("outside the contract shape" in p for p in agents.check_return("## Sources\n- context7 · fastapi\n## Answer\nx\n## Unknowns\nnone\n" + gov, "reader")), "a source that names no ref and no digest is refused")
            self.assertTrue(any("without a real ref or digest" in p for p in agents.check_return("## Sources\n- doc · web · q · n/a · -\n## Answer\nx\n## Unknowns\nnone\n" + gov, "reader")))
            self.assertTrue(any("names nothing searched" in p for p in agents.check_return("## Sources\nno sources\n## Answer\nx\n## Unknowns\n- is it async\n" + gov, "reader")))
            self.assertTrue(any("names nothing searched" in p for p in agents.check_return("## Sources\nno sources\n## Answer\nx\n## Unknowns\n- is it async · searched: \n" + gov, "reader")))
            self.assertTrue(any("no `## Governance`" in p for p in agents.check_return("## Sources\nno sources\n## Answer\nx\n## Unknowns\nnone\n", "reader")))
            # empty sections, the template echoed back, the order — refused
            self.assertTrue(any("empty `## Answer`" in p for p in agents.check_return("## Sources\nno sources\n## Answer\n## Unknowns\nnone\n" + gov, "reader")))
            self.assertTrue(any("empty `## Unknowns`" in p for p in agents.check_return("## Sources\nno sources\n## Answer\nx\n## Unknowns\n" + gov, "reader")))
            self.assertTrue(any("placeholder" in p for p in agents.check_return("## Sources\n- mcp · context7 · <query> · <ref: url> · <digest>\n## Answer\nx\n## Unknowns\nnone\n" + gov, "reader")), "the contract's own template is not a return")
            self.assertTrue(any("out of order" in p for p in agents.check_return("## Answer\nx\n## Sources\nno sources\n## Unknowns\nnone\n" + gov, "reader")))
            self.assertEqual(agents.check_return("## Sources\n(or exactly: no sources)\nno sources\n## Answer\nx\n## Unknowns\n- q · searched: web\n(or exactly: none)\n" + gov, "reader"), [], "the template's hint lines are not lines")
            self.assertTrue(any("exactly `## Sources`" in p for p in agents.check_return("## Sources (2)\n- mcp · context7 · q · https://x · d\n## Answer\nx\n## Unknowns\nnone\n" + gov, "reader")))
            self.assertEqual(agents.check_return("did x\n" + gov, "worker"), [], "the reader's sections are the reader's — a worker owes only its governance block")


class Seal(unittest.TestCase):
    """EVOL-051: one full verification loop — the documentation class (one definition), the path-to-gate map, the seal the push honours."""

    DOCS = {"paths": ["**/*.md", "docs/**", ".gitignore"], "exclusions": [".github/workflows/**", ".claude/skills/**"]}
    GATES = {"tests": {"reads": ["src/**", "tests/**"], "command": "pytest -q"},
             "coverage": {"reads": ["src/**", "tests/**"], "command": "pytest -q"},     # the same suite feeds coverage: one execution
             "lint": {"reads": ["src/**"], "command": "ruff check src"},
             "docs-build": {"reads": ["docs/site/**"], "command": "mkdocs build"}}       # a gate that DOES read documentation

    def _repo(self, tmp, required=True, gates=None):
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text())
        q["documentation"] = dict(self.DOCS)
        q["verification"] = {"seal": {"required": required, "dir": ".claude/state", "reason": "" if required else "CI is the loop"}, "gates": self.GATES if gates is None else gates, "digest_artefacts": ["design.md"]}
        write(repo / "config/quality.json", json.dumps(q))
        write(repo / "src/app.py", "print(1)\n"); write(repo / "tests/test_app.py", "def test_a(): pass\n"); write(repo / "docs/site/index.md", "# site\n")
        write(repo / ".gitignore", ".claude/state/\n")   # as the template ships it; the seal is never part of the tree it seals either way
        self._commit(repo, "base")
        subprocess.run(["git", "-C", str(repo), "branch", "-M", "main"], check=True, capture_output=True)   # the base is `main` whatever init.defaultBranch says (CI runners default to master)
        subprocess.run(["git", "-C", str(repo), "checkout", "-qb", "feature/FEAT-001-x"], check=True, capture_output=True)
        return repo

    def _commit(self, repo, msg="c"):
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", msg, "--allow-empty"], check=True, capture_output=True)

    def test_documentation_is_one_definition(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            cfg = seal.documentation_cfg(repo)
            self.assertTrue(seal.is_documentation("docs/x.md", cfg)[0]); self.assertTrue(seal.is_documentation("./README.md", cfg)[0])
            self.assertFalse(seal.is_documentation("src/docs/x.py", cfg)[0], "root-anchored: docs/** never covers src/docs")
            self.assertFalse(seal.is_documentation(".github/workflows/ci.md", cfg)[0], "an exclusion is code whatever its extension")
            self.assertFalse(seal.is_documentation(".claude/skills/x/SKILL.md", cfg)[0], "a behavioural contract is never documentation — even under **/*.md")
            # the planning gate reads the same definition (docs_exempt is retired)
            q = json.loads((repo / "config/quality.json").read_text())
            q["planning"] = {"governed_paths": ["src/**", "docs/**"], "gate_inputs": [], "exempt_classes": [], "plan_artefact": None}
            write(repo / "config/quality.json", json.dumps(q))
            self.assertEqual(planning.governed(repo, "docs/x.md")[0], False); self.assertEqual(planning.governed(repo, "src/a.py")[0], True)
            q["planning"]["docs_exempt"] = ["**/*.md"]; write(repo / "config/quality.json", json.dumps(q))
            with self.assertRaisesRegex(GateFault, "docs_exempt is retired"):
                planning.governed(repo, "docs/x.md")
            # docs-only over a diff (the config edits above are committed first: config is code)
            self._commit(repo, "cfg")
            write(repo / "docs/new.md", "x\n"); self._commit(repo, "docs")
            self.assertTrue(seal.docs_only(repo, "HEAD~1")["ok"], "the delta since the last commit is documentation")
            self.assertFalse(seal.docs_only(repo, "main")["ok"], "the branch as a whole carries the config edit: code")
            write(repo / "src/app.py", "print(2)\n"); self._commit(repo, "code")
            r = seal.docs_only(repo, "HEAD~1"); self.assertFalse(r["ok"]); self.assertEqual(r["code"], ["src/app.py"])
            del q["documentation"]; write(repo / "config/quality.json", json.dumps(q))
            with self.assertRaisesRegex(GateFault, "`documentation` is missing"):
                seal.docs_only(repo, "main")

    def test_tree_entries_hash_as_git_commits(self):
        """mode + blob id as the commit carries them: clean filters applied, a symlink by its target, the executable bit seen."""
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            write(repo / ".gitattributes", "*.txt text=auto\n"); (repo / "src" / "crlf.txt").write_bytes(b"a\r\nb\r\n")
            os.symlink("app.py", repo / "src" / "link.py"); (repo / "src" / "run.sh").write_text("#!/bin/sh\n"); os.chmod(repo / "src" / "run.sh", 0o755)
            disk = seal.tree_entries(repo)
            self._commit(repo, "special files")
            head = seal.tree_entries(repo, "HEAD")
            for path in ("src/crlf.txt", "src/link.py", "src/run.sh", "src/app.py"):
                self.assertEqual(disk[path], head[path], path)
            self.assertTrue(head["src/link.py"].startswith("120000:")); self.assertTrue(head["src/run.sh"].startswith("100755:"))
            os.chmod(repo / "src" / "run.sh", 0o644)
            self.assertNotEqual(seal.tree_entries(repo)["src/run.sh"], head["src/run.sh"], "a mode change moves the entry")
            self.assertNotIn(".claude/state/x", seal.tree_entries(repo, skip=".claude/state"))

    def test_seal_plan_write_check(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            B = "main"
            # no seal, nothing moved since the merge-base: nothing owed (a branch that changed nothing a gate reads pays no loop)
            r = seal.check(repo, base=B); self.assertTrue(r["ok"], r["reason"]); self.assertEqual(r["against"], "merge-base")
            self.assertEqual(seal.plan(repo, base=B)["owed"], [])
            # main moves under the branch (someone else's src change): the reference is the MERGE-BASE, the branch still owes nothing
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "main"], check=True, capture_output=True)
            write(repo / "src/other.py", "other\n"); self._commit(repo, "on main")
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "feature/FEAT-001-x"], check=True, capture_output=True)
            r = seal.check(repo, base=B); self.assertTrue(r["ok"], r["reason"])
            # a code change on the branch: the readers of src are owed — a shared command is ONE execution feeding two gates
            write(repo / "src/app.py", "print(2)\n"); self._commit(repo, "code")
            pl = seal.plan(repo, base=B)
            self.assertFalse(pl["full"]); self.assertEqual(pl["owed"], ["coverage", "lint", "tests"]); self.assertEqual(pl["paths"], ["src/app.py"], "an owed gate names the paths that moved")
            ex = {e["command"]: e["gates"] for e in pl["executions"]}
            self.assertEqual(ex["pytest -q"], ["coverage", "tests"], "a suite that feeds coverage is executed once inside the loop")
            self.assertEqual(len(pl["executions"]), 2)
            r = seal.check(repo, base=B); self.assertFalse(r["ok"]); self.assertEqual(r["against"], "merge-base"); self.assertIn("src/app.py", seal.render(r))
            # an unmapped path with no seal: the full loop
            write(repo / "config/x.json", "{}\n"); self._commit(repo, "cfg")
            pl = seal.plan(repo, base=B); self.assertTrue(pl["full"]); self.assertEqual(pl["owed"], ["coverage", "docs-build", "lint", "tests"]); self.assertEqual(len(pl["executions"]), 3)
            # at CI the seal is not on the runner: n/a with the honest reason (CI does not run the loop)
            r = seal.check(repo, control_point="ci", base=B); self.assertTrue(r["ok"]); self.assertFalse(r["required"]); self.assertIn("CI does not run the loop", r["reason"])
            # at the static round the answer is the plan's, advisory — never a blocker before the loop ran
            r = seal.check(repo, control_point="static", base=B); self.assertTrue(r["ok"]); self.assertTrue(r["advisory"]); self.assertEqual(r["owed"], ["coverage", "docs-build", "lint", "tests"])
            with self.assertRaisesRegex(GateFault, "not green yet"):
                seal.write(repo, ["tests"], ok=True, full=True)
            with self.assertRaisesRegex(GateFault, "unknown gate"):
                seal.write(repo, ["nope"], ok=True)
            with self.assertRaisesRegex(GateFault, "seals a green loop"):
                seal.write(repo, ["tests"], ok=False, full=True)
            # a green full loop on the tree ON DISK (an uncommitted edit included), then the commit carries those bytes: the push honours the seal
            write(repo / "src/app.py", "print(2)  # sealed before the commit\n")
            w = seal.write(repo, ["tests", "coverage", "lint", "docs-build"], ok=True, summary="green", full=True)
            self.assertTrue(w["full"]); self.assertTrue((repo / w["path"]).is_file())
            self.assertFalse(seal.check(repo, base=B)["ok"], "HEAD does not carry the sealed bytes yet")
            self._commit(repo, "sealed bytes")
            r = seal.check(repo, base=B); self.assertTrue(r["ok"], "the commit carries exactly the bytes the loop sealed"); self.assertEqual(r["against"], "seal"); self.assertEqual(seal.plan(repo, base=B)["owed"], [])
            # a documentation-only delta owes nothing — docs are in no read-set…
            write(repo / "docs/notes.md", "notes\n"); self._commit(repo, "docs")
            r = seal.check(repo, base=B); self.assertTrue(r["ok"], r["reason"])
            # …unless a gate declares it reads them (the red the issue asks for)
            write(repo / "docs/site/index.md", "# site v2\n"); self._commit(repo, "site docs")
            r = seal.check(repo, base=B); self.assertFalse(r["ok"]); self.assertEqual(r["owed"], ["docs-build"]); self.assertFalse(r["full"]); self.assertEqual(r["paths"], ["docs/site/index.md"])
            seal.write(repo, ["docs-build"], ok=True); self.assertTrue(seal.check(repo, base=B)["ok"], "the incremental seal: only the gate whose read-set moved re-ran")
            # a code delta owes exactly the gates that read it
            write(repo / "src/app.py", "print(3)\n"); self._commit(repo, "code")
            r = seal.check(repo, base=B); self.assertFalse(r["ok"]); self.assertEqual(r["owed"], ["coverage", "lint", "tests"])
            pl = seal.plan(repo, base=B); self.assertEqual({e["command"] for e in pl["executions"]}, {"pytest -q", "ruff check src"})
            seal.write(repo, ["tests", "coverage"], ok=True)
            r = seal.check(repo, base=B); self.assertEqual(r["owed"], ["lint"], "a partial re-run leaves the rest owed")
            seal.write(repo, ["lint"], ok=False, summary="ruff red")
            r = seal.check(repo, base=B); self.assertEqual(r["owed"], ["lint"], "a red run is not a seal")
            seal.write(repo, ["lint"], ok=True); self.assertTrue(seal.check(repo, base=B)["ok"])
            # --full must not re-hash: a read-set moved after its run (an auto-fix) is refused, never sealed
            write(repo / "src/app.py", "print(3)  # lint auto-fix after the suite ran\n")
            with self.assertRaisesRegex(GateFault, "read-set moved after its run.*re-run coverage, lint, tests"):
                seal.write(repo, [], ok=True, full=True)
            seal.write(repo, ["tests", "coverage", "lint"], ok=True); seal.write(repo, [], ok=True, full=True)
            self._commit(repo, "auto-fixed"); self.assertTrue(seal.check(repo, base=B)["ok"])
            # the gate-that-stops-firing defect: a changed path no gate reads and no documentation covers owes the FULL loop, fail closed
            write(repo / "config/feature.json", "{}\n"); self._commit(repo, "config")
            r = seal.check(repo, base=B); self.assertFalse(r["ok"]); self.assertTrue(r["full"]); self.assertEqual(r["unmapped"], ["config/feature.json"])
            self.assertEqual(seal.plan(repo, base=B)["owed"], ["coverage", "docs-build", "lint", "tests"])
            # reads are root-anchored like the documentation class: vendor/src is not src
            write(repo / "vendor/src/x.py", "v\n"); self._commit(repo, "vendor")
            r = seal.check(repo, base=B); self.assertIn("vendor/src/x.py", r["unmapped"], "src/** never covers vendor/src/x.py")
            (repo / "vendor/src/x.py").unlink(); (repo / "vendor/src").rmdir(); (repo / "vendor").rmdir(); self._commit(repo, "vendor gone")
            # an unstaged edit is seen by the plan (the disk) and not by the check (HEAD)
            seal.write(repo, ["tests", "coverage", "lint", "docs-build"], ok=True, full=True)
            self.assertTrue(seal.check(repo, base=B)["ok"], "sealed on the committed bytes")
            write(repo / "src/app.py", "print(4)\n")
            self.assertEqual(seal.plan(repo, base=B)["owed"], ["coverage", "lint", "tests"], "the plan reads the disk, not HEAD")
            self.assertTrue(seal.check(repo, base=B)["ok"], "the check reads HEAD: an uncommitted edit is not what the push carries")
            # the seal belongs to its branch
            subprocess.run(["git", "-C", str(repo), "checkout", "-qb", "feature/FEAT-002-y"], check=True, capture_output=True)
            sp = repo / ".claude/state/seal-feature-FEAT-002-y.json"; sp.write_text((repo / ".claude/state/seal-feature-FEAT-001-x.json").read_text())
            with self.assertRaisesRegex(GateFault, "written for branch"):
                seal.check(repo, base=B)
            sp.unlink(); subprocess.run(["git", "-C", str(repo), "checkout", "-q", "feature/FEAT-001-x"], check=True, capture_output=True)
            # not required: n/a with the reason; without a reason: RED (fail closed); required without a map: RED; config absent: RED, never a fault
            q = json.loads((repo / "config/quality.json").read_text()); q["verification"]["seal"] = {"required": False, "reason": "CI is the loop"}; write(repo / "config/quality.json", json.dumps(q))
            r = seal.check(repo, base=B); self.assertTrue(r["ok"]); self.assertFalse(r["required"]); self.assertIn("CI is the loop", seal.render(r))
            q["verification"]["seal"] = {"required": False}; write(repo / "config/quality.json", json.dumps(q))
            r = seal.check(repo, base=B); self.assertFalse(r["ok"]); self.assertIn("without a `reason`", r["reason"])
            q["verification"]["seal"] = {"required": True}; q["verification"]["gates"] = {}; write(repo / "config/quality.json", json.dumps(q))
            r = seal.check(repo, base=B); self.assertFalse(r["ok"]); self.assertIn("gates is empty", r["reason"])
            pl = seal.plan(repo, base=B); self.assertFalse(pl["ok"], "an empty map never plans 'nothing owed'")
            self.assertTrue(any("gates is empty" in x["reason"] for x in seal.validate(repo)))
            q["verification"]["gates"] = {"tests": {"reads": []}}; write(repo / "config/quality.json", json.dumps(q))
            r = seal.check(repo, base=B); self.assertFalse(r["ok"]); self.assertIn("non-empty `reads`", r["reason"])
            q["verification"]["seal"] = {"required": True, "dir": "/tmp/elsewhere"}; q["verification"]["gates"] = self.GATES; write(repo / "config/quality.json", json.dumps(q))
            r = seal.check(repo, base=B); self.assertFalse(r["ok"]); self.assertIn("inside the repository", r["reason"])
            del q["verification"]; write(repo / "config/quality.json", json.dumps(q))
            r = seal.check(repo, base=B); self.assertFalse(r["ok"]); self.assertIn("`verification` is missing", r["reason"])
            q["verification"] = {"seal": {"required": True, "dir": "./.claude/state/"}, "gates": self.GATES}; write(repo / "config/quality.json", json.dumps(q))
            self.assertEqual(seal.vcfg(repo)["dir"], ".claude/state", "the seal dir is normalised so its own folder is skipped")
            (repo / ".claude/state/seal-feature-FEAT-001-x.json").write_text("{nope", encoding="utf-8")
            with self.assertRaisesRegex(GateFault, "unreadable"):
                seal.check(repo, base=B)
            (repo / ".claude/state/seal-feature-FEAT-001-x.json").unlink()
            with self.assertRaisesRegex(GateFault, "not a commit this clone knows"):
                seal.plan(repo, base="nowhere/nope")

    def test_traceability_is_a_light_member(self):
        self.assertIn("traceability", {m["member"] for m in profile.owed("light")}, "the traceability gate runs at the static round, the push and CI")

    def test_static_round_is_light_whatever_the_mode(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            write(repo / "docs/project_log/governance_versions.json", json.dumps({"delivery_mode": "production", "templates": {}}))
            self.assertEqual(profile.profile(repo, "feature/FEAT-001-x", "static")["profile"], "light", "the static round: no build, no database, whatever the class or the mode")
            self.assertEqual(profile.profile(repo, "feature/FEAT-001-x", "push")["profile"], "full")


class Digests(unittest.TestCase):
    """EVOL-051: the loop checks what the push checks — every planning artefact of the feature carries a current, complete governance digest."""

    def _repo(self, tmp):
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text())
        q["documentation"] = {"paths": ["**/*.md", "docs/**"], "exclusions": []}
        q["verification"] = {"seal": {"required": False, "reason": "n/a"}, "gates": {}, "digest_artefacts": ["design.md", "dev_plan.md"]}
        write(repo / "config/quality.json", json.dumps(q))
        write(repo / ".context/governance_snapshot.md", "---\nconstitution_hash: abcdef1234567890\nsetup_hash: x\n---\n")
        write(repo / ".claude/rules/security_policy.md", "---\ndescription: s\napplicable_when:\n  path_glob: [\"src/**\"]\n---\n")
        write(repo / ".claude/rules/testing.md", "---\ndescription: t\napplicable_when:\n  always: true\n---\n")
        write(repo / ".claude/rules/ci-cd.md", "---\ndescription: c\napplicable_when:\n  path_glob: [\".github/workflows/**\"]\n---\n")
        write(repo / ".github/workflows/ci.yml", "on: push\n")
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "base"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(repo), "branch", "-M", "main"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(repo), "checkout", "-qb", "feature/FEAT-001-x"], check=True, capture_output=True)
        return repo

    def _commit(self, repo, msg="c"):
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", msg], check=True, capture_output=True)

    def test_digest_currency_and_completeness(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            self.assertEqual(digests.feature_id("feature/FEAT-001-x"), "FEAT-001"); self.assertEqual(digests.feature_id("feature/FEAT-001-inc-1-x-sub-2"), "FEAT-001"); self.assertIsNone(digests.feature_id("fix/x"))
            self.assertEqual(digests.fingerprint(repo), "abcdef12")
            r = digests.check(repo, "main"); self.assertTrue(r["ok"]); self.assertIn("nothing to judge", r["reason"])
            # an empty change binds the always-on rules only — never the whole tree (ci-cd is NOT bound: no workflow changed)
            self.assertNotIn("ci-cd", digests.bound_rules(repo, "main")); self.assertIn("testing", digests.bound_rules(repo, "main"))
            # the change on DISK binds — the static round runs before the commit
            write(repo / "src/app.py", "print(2)\n")
            self.assertIn("security_policy", digests.bound_rules(repo, "main"), "an uncommitted src change binds security_policy")
            # completeness is a REFERENCE (rules/<name>.md), never a bare word in prose
            write(repo / "docs/spec/FEAT-001/design.md", "---\ngovernance_digest_version: \"abcdef12\"\n---\n## 7. GCD\nWe defer testing to QA; security_policy applies.\n```\nrules/testing.md\n```\n")
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("incomplete", r["artefacts"][0]["reason"]); self.assertIn("testing", r["artefacts"][0]["reason"]); self.assertIn("security_policy", r["artefacts"][0]["reason"])
            write(repo / "docs/spec/FEAT-001/design.md", "---\ngovernance_digest_version: \"abcdef12\"\n---\n## 7. GCD\n" + "".join(f"- rules/{r}.md\n" for r in digests.bound_rules(repo, "main")))
            r = digests.check(repo, "main"); self.assertTrue(r["ok"], r)
            self._commit(repo, "code + design")
            r = digests.check(repo, "main"); self.assertTrue(r["ok"], r)
            # a stale fingerprint; at CI the fingerprint is n/a (no snapshot on the runner), completeness still judged
            write(repo / ".context/governance_snapshot.md", "---\nconstitution_hash: 9999999999\n---\n")
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("stale", r["artefacts"][0]["reason"])
            r = digests.check(repo, "main", control_point="ci"); self.assertTrue(r["ok"], r); self.assertIn("fingerprint n/a at ci", r["reason"])
            write(repo / ".context/governance_snapshot.md", "---\nconstitution_hash: abcdef1234567890\n---\n")
            # THE red the issue asks for: a corpus item appears (a new rule bound to this surface) — an UNTOUCHED artefact's digest is incomplete
            write(repo / ".claude/rules/privacy.md", "---\ndescription: p\napplicable_when:\n  path_glob: [\"src/**\"]\n---\n")
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("incomplete", r["artefacts"][0]["reason"]); self.assertIn("privacy", r["artefacts"][0]["reason"])
            (repo / ".claude/rules/privacy.md").unlink()
            # a second artefact without any digest; a missing snapshot downstream is RED (governance not delivered), never a fault the push walks past
            write(repo / "docs/spec/FEAT-001/dev_plan.md", "---\nstatus: READY\n---\n- rules/security_policy.md\n- rules/testing.md\n")
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("never generated", [a for a in r["artefacts"] if a["artefact"].endswith("dev_plan.md")][0]["reason"])
            self.assertIn("✗ docs/spec/FEAT-001/dev_plan.md", digests.render(r))
            (repo / ".context/governance_snapshot.md").unlink()
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("governance_snapshot.md is missing", r["artefacts"][0]["reason"])
            q = json.loads((repo / "config/quality.json").read_text()); del q["verification"]; write(repo / "config/quality.json", json.dumps(q))
            r = digests.check(repo, "main"); self.assertFalse(r["ok"]); self.assertIn("`verification` is missing", r["reason"]); self.assertIn("RED", digests.render(r))



class Traceability(unittest.TestCase):
    """EVOL-053: one machine-readable home for the case → test link — strict ids, case → test, a shrink-only baseline."""

    PLAN = """---\nid: FEAT-001\nstatus: APPROVED\n---\n# Test Cases\n\n## 1. Acceptance\n| ID | Gherkin Ref | Business Scenario | Expected |\n|----|---|---|---|\n| AC-01 | Happy path | Login | Dashboard |\n\n## 2. Technical\n| ID | Type | Technical Scenario | Input | Expected |\n|----|---|---|---|---|\n| TC-01 | Edge | DB timeout | down | 503 |\n| TC-API-01 | /login | POST | ok | 200 |\n\n## 3. Standards (not cases)\n| Standard | Notes |\n|---|---|\n| ISO-8601 | dates |\n| HTTP-401 | unauthenticated |\n\n```markdown\n| ID | Type |\n|---|---|\n| TC-99 | a sample inside a fence declares nothing |\n```\n"""

    def _repo(self, tmp, kind="pytest-marker", required=True):
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text())
        q["traceability"] = {"required": required, "reason": "" if required else "no plans here", "home": {"kind": kind}, "plans": "docs/spec/*/test_plan.md",
                             "test_roots": ["tests/**", "src/**/*.test.*", "src/test/**"], "baseline": "docs/project_log/traceability_baseline.json"}
        write(repo / "config/quality.json", json.dumps(q))
        write(repo / "docs/spec/FEAT-001/test_plan.md", self.PLAN)
        self._commit(repo, "plan")
        return repo

    def _commit(self, repo, msg="c"):
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True, capture_output=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", msg, "--allow-empty"], check=True, capture_output=True)

    def test_declared_links_and_the_ratchet(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            c = traceability.cfg(repo)
            dec, bad = traceability.declared(repo, c)
            self.assertEqual(sorted(dec), ["FEAT-001/AC-01", "FEAT-001/TC-01", "FEAT-001/TC-API-01"], "only ID tables outside fences declare; a standards table is not a plan")
            self.assertEqual(bad, [])
            # no test yet: every case unlinked, none in the baseline → red, each named; --init refuses when NOTHING links (a misconfiguration, not debt)
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertEqual(r["unlinked"], sorted(dec)); self.assertEqual(len(r["new_debt"]), 3)
            with self.assertRaisesRegex(GateFault, "no test links any"):
                traceability.baseline(repo, init=True)
            # an UNTRACKED test on disk links (the static round runs before git add); a comment or a docstring is text, not a marker
            write(repo / "tests/test_login.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/AC-01")\ndef test_login(): pass\n\n# @pytest.mark.case("FEAT-001/TC-01")\ndef test_commented():\n    """@pytest.mark.case("FEAT-001/TC-API-01") lives in a docstring: not a marker"""\n    pass\n')
            r = traceability.check(repo); self.assertEqual(r["linked"], 1); self.assertIn("FEAT-001/TC-01", r["unlinked"]); self.assertIn("FEAT-001/TC-API-01", r["unlinked"])
            # the baseline records the debt ONCE; the file must be committed (CI reads the commit); then green with the debt on the board
            b = traceability.baseline(repo, init=True); self.assertEqual(b["unlinked"], ["FEAT-001/TC-01", "FEAT-001/TC-API-01"]); self.assertIn("commit", b["note"])
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertTrue(any("git does not track it" in f["reason"] for f in r["findings"]))
            self._commit(repo, "baseline + test")
            with self.assertRaisesRegex(GateFault, "only shrinks"):
                traceability.baseline(repo, init=True)
            r = traceability.check(repo); self.assertTrue(r["ok"], r["findings"]); self.assertEqual(r["linked"], 1)
            self.assertEqual({x["id"]: x["status"] for x in r["cases"]}, {"FEAT-001/AC-01": "linked", "FEAT-001/TC-01": "unlinked-baseline", "FEAT-001/TC-API-01": "unlinked-baseline"})
            self.assertEqual([x["tests"] for x in r["cases"] if x["id"] == "FEAT-001/AC-01"], [["tests/test_login.py:3"]], "QA reads the linked test from the gate, never re-derives it")
            # more marker forms: a class marker, the module's pytestmark, `from pytest import mark`, pytest.param(marks=…); a skipped test proves no case
            write(repo / "tests/test_more.py", 'import pytest\nfrom pytest import mark\n\npytestmark = pytest.mark.case("FEAT-001/TC-01")\n\n@mark.case("FEAT-001/TC-API-01")\nclass TestApi:\n    def test_ok(self): pass\n\n@pytest.mark.skip(reason="wip")\n@pytest.mark.case("FEAT-001/AC-01")\ndef test_skipped(): pass\n')
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertEqual(r["shrink"], ["FEAT-001/TC-01", "FEAT-001/TC-API-01"]); self.assertEqual(r["linked"], 3)
            self.assertEqual([x["tests"] for x in r["cases"] if x["id"] == "FEAT-001/AC-01"], [["tests/test_login.py:3"]], "the skipped test is not a link")
            b = traceability.baseline(repo, refresh=True); self.assertEqual(b["removed"], ["FEAT-001/TC-01", "FEAT-001/TC-API-01"]); self.assertEqual(b["unlinked"], [])
            self._commit(repo, "linked"); r = traceability.check(repo); self.assertTrue(r["ok"], r["findings"])
            # a NEW case declared after the baseline must link — the baseline never grows; a MANUAL case (Tool: Manual …) is never owed
            write(repo / "docs/spec/FEAT-001/test_plan.md", self.PLAN + "\n## 4. UX\n| ID | Test Case | Tool | Expected |\n|---|---|---|---|\n| UX-01 | Responsive | Manual + Lighthouse | adapts |\n| TC-02 | Edge | pytest | 200 |\n")
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertEqual(r["new_debt"], ["FEAT-001/TC-02"]); self.assertEqual(r["manual"], 1)
            self.assertEqual([x["status"] for x in r["cases"] if x["id"] == "FEAT-001/UX-01"], ["manual"])
            b = traceability.baseline(repo, refresh=True); self.assertEqual(b["unlinked"], [], "refresh never adds")
            write(repo / "tests/test_cache.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/TC-02")\ndef test_cache(): pass\n')
            self._commit(repo, "tc-02"); self.assertTrue(traceability.check(repo)["ok"])
            # a case → test link is required; test → case never is: a helper test with no marker is not a finding; a conftest is never scanned
            write(repo / "tests/test_helper.py", "def test_helper(): pass\n"); write(repo / "tests/conftest.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/AC-01")\ndef fixture_like(): pass\n')
            r = traceability.check(repo); self.assertTrue(r["ok"], r["findings"]); self.assertEqual([x["tests"] for x in r["cases"] if x["id"] == "FEAT-001/AC-01"], [["tests/test_login.py:3"]])
            # an unknown link is as wrong as a case with no test; a malformed id is red; an unparseable test file is red
            write(repo / "tests/test_bad.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/TC-99")\ndef test_ghost(): pass\n\n@pytest.mark.case("tc01")\ndef test_typo(): pass\n')
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertEqual(r["unknown"], ["FEAT-001/TC-99"])
            self.assertEqual(sorted(f["path"] for f in r["findings"]), ["tests/test_bad.py:3", "tests/test_bad.py:6"])
            write(repo / "tests/test_bad.py", "def broken(:\n")
            r = traceability.check(repo); self.assertTrue(any("does not parse" in f["reason"] for f in r["findings"]))
            (repo / "tests/test_bad.py").unlink()
            # a tracked test deleted on disk is simply gone (never a crash): its case is unlinked again
            (repo / "tests/test_cache.py").unlink()
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertEqual(r["new_debt"], ["FEAT-001/TC-02"])
            self._commit(repo, "tc-02 test gone")
            # a stale baseline entry (its case gone from the plan) is red until removed; a duplicate row is red; a grammar-failing id in an ID table is red
            write(repo / "docs/project_log/traceability_baseline.json", json.dumps({"unlinked": ["FEAT-001/TC-02", "FEAT-001/GONE-01"]}))
            r = traceability.check(repo); self.assertEqual(r["stale"], ["FEAT-001/GONE-01"])
            b = traceability.baseline(repo, refresh=True); self.assertEqual(b["unlinked"], ["FEAT-001/TC-02"]); self._commit(repo, "baseline")
            self.assertTrue(traceability.check(repo)["ok"])
            write(repo / "docs/spec/FEAT-001/test_plan.md", self.PLAN + "\n| ID | Type |\n|---|---|\n| TC-01 | again |\n| TC-1 | x |\n")
            r = traceability.check(repo)
            self.assertTrue(any("declared twice" in f["reason"] for f in r["findings"])); self.assertTrue(any("fails the grammar" in f["reason"] for f in r["findings"]))
            # a plans glob that names nothing while a plan exists is red; no plan at all is ok ("no test plan declares a case yet")
            q = json.loads((repo / "config/quality.json").read_text()); q["traceability"]["plans"] = "docs/plans/*/test_plan.md"; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertTrue(any("matches nothing while a test plan exists" in f["reason"] for f in r["findings"]))
            (repo / "docs/spec/FEAT-001/test_plan.md").unlink(); (repo / "docs/project_log/traceability_baseline.json").unlink(); self._commit(repo, "no plan")
            q["traceability"]["plans"] = "docs/spec/*/test_plan.md"; write(repo / "config/quality.json", json.dumps(q))
            for f in (repo / "tests").glob("test_*.py"):
                f.unlink()
            r = traceability.check(repo); self.assertTrue(r["ok"]); self.assertIn("no test plan declares", r["reason"])
            # a corrupt baseline is a fault; a missing config block is RED, never a fault; not required = n/a with its reason, red without one
            write(repo / "docs/project_log/traceability_baseline.json", "{nope")
            with self.assertRaisesRegex(GateFault, "unreadable"):
                traceability.check(repo)
            (repo / "docs/project_log/traceability_baseline.json").unlink()
            q["traceability"]["required"] = False; q["traceability"]["reason"] = ""; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertIn("without a `reason`", r["reason"])
            q["traceability"]["reason"] = "no plans here"; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertTrue(r["ok"]); self.assertFalse(r["required"]); self.assertIn("n/a", traceability.render(r))
            del q["traceability"]; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertIn("`traceability` is missing", r["reason"])

    def test_title_tag_and_junit_homes(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp, kind="title-tag")
            write(repo / "src/login.test.ts", 'import { test } from "vitest";\ntest("[FEAT-001/AC-01] logs in", () => {});\nit.only("[FEAT-001/TC-01] times out", () => {});\ndescribe("[FEAT-001/TC-API-01] POST /login", () => { it("ok", () => {}); });\n// test("[FEAT-001/TC-API-01] commented out", () => {});\ntest.skip("[FEAT-001/TC-API-01] skipped", () => {});\n')
            r = traceability.check(repo); self.assertEqual(r["linked"], 2, "a describe, a comment and a skipped test link nothing"); self.assertEqual(r["unlinked"], ["FEAT-001/TC-API-01"])
            write(repo / "src/api.test.ts", 'test.each([1, 2])("[FEAT-001/TC-API-01] status %i", (i) => {});\n')
            r = traceability.check(repo); self.assertEqual(r["linked"], 3, "test.each links")
            write(repo / "src/other.test.ts", 'test("[FEAT-001/tc-01] lower", () => {});\n')
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertTrue(any("is not a case link" in f["reason"] for f in r["findings"]))
            (repo / "src/other.test.ts").unlink()
            # JUnit: @DisplayName is the home
            q = json.loads((repo / "config/quality.json").read_text()); q["traceability"]["home"] = {"kind": "junit-displayname"}; write(repo / "config/quality.json", json.dumps(q))
            write(repo / "src/test/LoginTest.java", 'class LoginTest {\n  @Test\n  @DisplayName("[FEAT-001/AC-01] logs in")\n  void login() {}\n  // @DisplayName("[FEAT-001/TC-01] commented")\n}\n')
            r = traceability.check(repo); self.assertEqual([x["status"] for x in r["cases"] if x["id"] == "FEAT-001/AC-01"], ["linked"]); self.assertIn("FEAT-001/TC-01", r["unlinked"])
            # custom: a pattern with a named group id is the ONLY home; an unknown kind is red
            q["traceability"]["home"] = {"kind": "custom"}; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertIn("needs a `pattern`", r["reason"])
            q["traceability"]["home"] = {"kind": "custom", "pattern": "case=(?P<id>[^ ]+)"}; write(repo / "config/quality.json", json.dumps(q))
            write(repo / "src/test/x.swift", "// case=FEAT-001/TC-01\n")
            r = traceability.check(repo); self.assertEqual([x["id"] for x in r["cases"] if x["status"] == "linked"], ["FEAT-001/TC-01"], "a custom home scans every text file under the roots")
            q["traceability"]["home"] = {"kind": "nope"}; write(repo / "config/quality.json", json.dumps(q))
            r = traceability.check(repo); self.assertFalse(r["ok"]); self.assertIn("not one of", r["reason"])

    def test_pytest_plugin_refuses_collection_on_an_unknown_id(self):
        if not importlib.util.find_spec("pytest"):
            if os.environ.get("CI"):
                self.fail("pytest is not installed on the CI runner — the collection plugin's red must run there (governance-check.yml installs pytest)")
            self.skipTest("pytest is not installed here")
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            import shutil
            (repo / "tests").mkdir(exist_ok=True); (repo / "scripts").mkdir(exist_ok=True)
            shutil.copy(HERE.parent / "gate.py", repo / "scripts/gate.py"); shutil.copytree(HERE, repo / "scripts/gates", ignore=shutil.ignore_patterns("test_*", "__pycache__"))
            shutil.copy(HERE.parent.parent / ".context/templates/setup/tests/conftest_traceability.py", repo / "tests/conftest_traceability.py")
            write(repo / "tests/conftest.py", 'pytest_plugins = ["conftest_traceability"]\n')
            write(repo / "tests/test_ok.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/AC-01")\ndef test_ok(): pass\n')
            env = {**os.environ, "PYTHONDONTWRITEBYTECODE": "1"}
            def run(*extra):
                return subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", *extra, "tests"], cwd=str(repo), capture_output=True, text=True, env=env)
            r = run(); self.assertNotEqual(r.returncode, 0); self.assertIn("--strict-markers", r.stdout + r.stderr, "the plugin refuses to run without strict markers")
            r = run("--strict-markers"); self.assertEqual(r.returncode, 0, r.stdout + r.stderr)
            write(repo / "tests/test_ghost.py", 'import pytest\n\n@pytest.mark.case("FEAT-001/TC-99")\ndef test_ghost(): pass\n')
            r = run("--strict-markers"); self.assertNotEqual(r.returncode, 0); self.assertIn("collection refused", r.stdout + r.stderr); self.assertIn("FEAT-001/TC-99", r.stdout + r.stderr)
            (repo / "tests/test_ghost.py").unlink()
            q = json.loads((repo / "config/quality.json").read_text()); q["traceability"] = {"required": False, "reason": "switched off"}; write(repo / "config/quality.json", json.dumps(q))
            r = run("--strict-markers"); self.assertEqual(r.returncode, 0, "required: false — the plugin does nothing, the suite runs")


class MiniYaml(unittest.TestCase):
    """The subset parser reads what this framework's frontmatter writes — flow mappings and lists included — so a project
    without PyYAML gets the same policy, never a silently empty roster."""

    def test_flow_collections_match_pyyaml(self):
        from gates.common import _mini_yaml
        text = RULE_AGENTS.split("---")[1]
        got = _mini_yaml(text)
        self.assertEqual(got["agents"]["roster"][0], {"name": "factory-dev-backend", "class": "worker", "surface": ["src/**"]})
        self.assertEqual(got["agents"]["classes"]["worker"]["tools"], {"must": ["Read", "Edit", "Write", "Bash"], "never": ["Agent"]})
        self.assertEqual(got["agents"]["tiers"], {"small": {"files": 5, "lines": 150}, "large": {"files": 30, "lines": 800}})
        self.assertEqual(got["agents"]["ladder"], {"critic": ["writer"], "writer": []})
        self.assertEqual(got["agents"]["resolve"][1], {"class": "plan-critic", "round": 2, "effort": "max"})
        self.assertEqual(_mini_yaml('x: [1, "a, b", {k: [true, null]}]')["x"], [1, "a, b", {"k": [True, None]}])
        try:
            import yaml
            self.assertEqual(got, yaml.safe_load(text), "the subset parser and PyYAML read the same structure")
        except ImportError:
            pass
        with self.assertRaisesRegex(GateFault, "unterminated"):
            _mini_yaml("x: [1, 2")

    def test_real_roster_without_pyyaml(self):
        """The delivered reader on the framework's own roster with PyYAML hidden: the validator is green and the spawn hook refuses — never a silently empty roster."""
        with tempfile.TemporaryDirectory() as tmp:
            write(Path(tmp) / "yaml.py", "raise ImportError('PyYAML hidden for the test')\n")
            env = {**os.environ, "PYTHONPATH": tmp, "PYTHONDONTWRITEBYTECODE": "1"}
            root = HERE.parent.parent; gate = str(HERE.parent / "gate.py")
            r = subprocess.run([sys.executable, gate, "--repo", str(root), "agents"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0, r.stdout + r.stderr)
            r = subprocess.run([sys.executable, gate, "--repo", str(root), "agents", "--spawn", "--agent", "factory-critic-security", "--model", "sonnet"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1, "a critic on the writer's alias is refused with the subset parser too"); self.assertIn("its family's alias", r.stdout)



class Scm(unittest.TestCase):
    """EVOL-054: the branch rule defended on the server — one reader, adapters per platform, RED on a missing setting, n/a where it cannot see.
    Every stub answers the repository probe first: a server the token cannot see is a fault, never four red findings about a branch nobody looked at."""

    FULL = [{"type": "non_fast_forward"}, {"type": "deletion"}, {"type": "pull_request", "parameters": {"required_approving_review_count": 0}},
            {"type": "required_status_checks", "parameters": {"required_status_checks": [{"context": "governance-check"}, {"context": "lockstep"}]}}]
    NEEDLES = ("pull request is not required", "force-push forbidden is not set", "deletion forbidden is not set")

    def _repo(self, tmp, platform="GitHub", approvals=0, checks=("governance-check",), required=True, branches=("main",)):
        os.makedirs(tmp, exist_ok=True)
        repo = fixture_repo(Path(tmp))
        q = json.loads((repo / "config/quality.json").read_text())
        q["scm"] = {"required": required, "reason": "" if required else "no server", "platform": platform, "protected_branches": list(branches), "required_checks": list(checks), "approvals": approvals}
        write(repo / "config/quality.json", json.dumps(q)); return repo

    @staticmethod
    def _rs(rules, rid=7, enforcement="active", include=("~DEFAULT_BRANCH",), exclude=(), bypass=None, name="protect main"):
        return {"id": rid, "name": name, "enforcement": enforcement, "conditions": {"ref_name": {"include": list(include), "exclude": list(exclude)}}, "bypass_actors": bypass, "rules": rules}

    @staticmethod
    def _gh(rulesets=(), legacy=None, default="main", branches=("main",)):
        """The GitHub API as the adapter walks it: the repository, the branch, the rulesets list + detail, the legacy protection."""
        def fetch(url, headers, missing_ok=False):
            rest = url.split("/repos/acme/app", 1)[1].lstrip("/")
            if rest == "":
                return {"default_branch": default}
            if rest.startswith("branches/") and not rest.endswith("/protection"):
                b = urllib.parse.unquote(rest[len("branches/"):])
                if b in branches:
                    return {"name": b}
                if missing_ok:
                    return None
                raise GateFault(f"nothing at {url} (404)")
            if rest == "rulesets?targets=branch":
                return [{"id": r["id"]} for r in rulesets]
            if rest.startswith("rulesets/"):
                return next(r for r in rulesets if r["id"] == int(rest.split("/")[1]))
            if rest.endswith("/protection"):
                if legacy == "forbidden":
                    raise GateFault("the SCM API refused (403) — the token lacks the scope")
                return legacy
            raise AssertionError(url)
        return fetch

    def _findings_once(self, r, *needles):
        joined = " | ".join(r["findings"])
        for n in needles:
            self.assertEqual(joined.count(n), 1, f"{n!r} expected exactly once in {r['findings']}")

    def test_remote_and_tokens(self):
        r = scm.remote(Path("."), "git@github.com:acme/app.git"); self.assertEqual((r["host"], r["owner"], r["repo"]), ("github.com", "acme", "app"))
        r = scm.remote(Path("."), "https://gitlab.com/group/sub/proj.git"); self.assertEqual((r["owner"], r["repo"]), ("group/sub", "proj"))
        r = scm.remote(Path("."), "https://user@bitbucket.org/ws/slug"); self.assertEqual((r["host"], r["owner"], r["repo"]), ("bitbucket.org", "ws", "slug"))
        r = scm.remote(Path("."), "https://dev.azure.com/org/Proj/_git/repo"); self.assertEqual((r["owner"], r["project"], r["repo"]), ("org", "Proj", "repo"))
        r = scm.remote(Path("."), "git@ssh.dev.azure.com:v3/org/Proj/repo"); self.assertEqual((r["owner"], r["project"], r["repo"]), ("org", "Proj", "repo"))
        # a port is not an owner; the old visualstudio host; url-encoded segments; DefaultCollection
        r = scm.remote(Path("."), "ssh://git@github.com:2222/acme/app.git"); self.assertEqual((r["host"], r["owner"], r["repo"]), ("github.com", "acme", "app"))
        r = scm.remote(Path("."), "https://github.com:8443/acme/app.git"); self.assertEqual((r["host"], r["owner"], r["repo"]), ("github.com", "acme", "app"))
        r = scm.remote(Path("."), "https://org.visualstudio.com/Proj/_git/repo"); self.assertEqual((r["owner"], r["project"], r["repo"]), ("org", "Proj", "repo"))
        r = scm.remote(Path("."), "https://dev.azure.com/org/DefaultCollection/My%20Proj/_git/repo"); self.assertEqual((r["project"], r["repo"]), ("My Proj", "repo"))
        r = scm.remote(Path("."), "https://gitlab.com/g/my%20proj.git"); self.assertEqual(r["repo"], "my proj")
        with self.assertRaisesRegex(GateFault, "not one this reader understands"):
            scm.remote(Path("."), "nonsense")
        with self.assertRaisesRegex(GateFault, "names no owner/repo"):
            scm.remote(Path("."), "https://github.com/onlyowner")
        self.assertEqual(scm.token("GitHub", {"GH_TOKEN": "t"}), "t"); self.assertIsNone(scm.token("GitLab", {"GH_TOKEN": "t"})); self.assertIsNone(scm.token("Other", {}))

    def test_fetch_json_is_honest_about_every_error(self):
        import email.message
        import io
        from unittest import mock
        def http_error(code, headers=None):
            h = email.message.Message()
            for k, v in (headers or {}).items():
                h[k] = v
            return urllib.error.HTTPError("https://api.x/y?q=1", code, "msg", h, io.BytesIO(b""))
        with mock.patch.object(scm.time, "sleep"), mock.patch.object(scm.urllib.request, "urlopen") as uo:
            uo.return_value = io.BytesIO(b'{"a": 1}')
            self.assertEqual(scm.fetch_json("https://api.x/y", {}), {"a": 1})
            uo.side_effect = http_error(404)
            self.assertIsNone(scm.fetch_json("https://api.x/y", {}, missing_ok=True), "404 is an answer only where a missing thing is one")
            with self.assertRaisesRegex(GateFault, "not visible to this token, or origin names the wrong one"):
                scm.fetch_json("https://api.x/y", {})
            for code in (401, 403):
                uo.side_effect = http_error(code)
                with self.assertRaisesRegex(GateFault, "lacks the scope"):
                    scm.fetch_json("https://api.x/y", {})
            uo.reset_mock(); uo.side_effect = http_error(500)
            with self.assertRaisesRegex(GateFault, "transient: re-run"):
                scm.fetch_json("https://api.x/y?q=1", {})
            self.assertEqual(uo.call_count, 2, "a 5xx is retried once, then a fault")
            uo.reset_mock(); uo.side_effect = http_error(403, {"x-ratelimit-remaining": "0"})
            with self.assertRaisesRegex(GateFault, "transient"):
                scm.fetch_json("https://api.x/y", {})
            self.assertEqual(uo.call_count, 2, "a rate-limited 403 is not a scope error")
            uo.reset_mock(); uo.side_effect = urllib.error.URLError("refused")
            with self.assertRaisesRegex(GateFault, "could not be reached .* a fault, never a pass"):
                scm.fetch_json("https://api.x/y", {})
            self.assertEqual(uo.call_count, 2)

    def test_github_green_red_and_the_control_points(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp, checks=("governance-check", "lockstep"))
            env = {"GH_TOKEN": "t"}; origin = "git@github.com:acme/app.git"
            gh = lambda *a, **k: self._gh(*a, **k)   # noqa: E731
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL)], legacy="forbidden"), env=env, origin=origin)
            self.assertTrue(r["ok"], r); self.assertEqual(r["status"], "ok"); self.assertEqual(r["repository"], "acme/app")
            b = r["branches"]["main"]
            self.assertEqual(b["checks"], ["governance-check", "lockstep"]); self.assertTrue(b["pr_required"] and b["force_push_blocked"] and b["deletion_blocked"]); self.assertEqual(b["approvals"], 0)
            self.assertEqual(b["unverifiable"], ["the bypass list (not exposed to this token)"], "bypass_actors absent from the payload = not exposed, listed")
            self.assertIn("scm-protection: ok", scm.render(r))
            # every missing setting is named exactly once: no PR rule, a check the server does not require, force-push and deletion open
            r = scm.check(repo, "ci", fetch=gh([self._rs([{"type": "required_status_checks", "parameters": {"required_status_checks": [{"context": "governance-check"}]}}], bypass=[])]), env=env, origin=origin)
            self.assertFalse(r["ok"]); self.assertEqual(r["status"], "RED"); self.assertEqual(len(r["findings"]), 4)
            self._findings_once(r, *self.NEEDLES, "not enforced by the server: lockstep")
            b = r["branches"]["main"]; self.assertFalse(b["pr_required"]); self.assertFalse(b["force_push_blocked"]); self.assertFalse(b["deletion_blocked"])
            self.assertIn("docs/scm/protection.md", r["reason"]); self.assertIn("RED", scm.render(r))
            repo2 = self._repo(tmp + "/x", approvals=2)
            r = scm.check(repo2, "ci", fetch=gh([self._rs(self.FULL)]), env=env, origin=origin); self.assertFalse(r["ok"]); self._findings_once(r, "0 approval(s) required, the project decided 2")
            # a ruleset in evaluation defends nothing; the legacy branch protection counts when present
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, enforcement="evaluate")]), env=env, origin=origin); self.assertFalse(r["ok"]); self.assertEqual(len(r["findings"]), 4)
            legacy = {"required_pull_request_reviews": {"required_approving_review_count": 0}, "required_status_checks": {"contexts": ["governance-check", "lockstep"]}, "allow_force_pushes": {"enabled": False}, "allow_deletions": {"enabled": False}}
            r = scm.check(repo, "ci", fetch=gh([], legacy=legacy), env=env, origin=origin); self.assertTrue(r["ok"], r)
            # the ruleset must reach the branch: an exclude, a scoped include, ~DEFAULT_BRANCH when the default is another branch — all RED; a glob include is honoured
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, include=("~ALL",), exclude=("refs/heads/main",))]), env=env, origin=origin); self.assertFalse(r["ok"], "excluded on the server = unprotected")
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, include=("refs/heads/release/*",))]), env=env, origin=origin); self.assertFalse(r["ok"], "a ruleset for release/* protects nothing on main")
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL)], default="develop"), env=env, origin=origin); self.assertFalse(r["ok"], "~DEFAULT_BRANCH is the server's default branch, not the configured one")
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, include=("refs/heads/ma*",))]), env=env, origin=origin); self.assertTrue(r["ok"], r)
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, include=("~ALL",))]), env=env, origin=origin); self.assertTrue(r["ok"], r)
            # a bypass actor is a hole with a name — RED; a pull-request-only bypass is not
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, bypass=[{"actor_id": 5, "actor_type": "Team", "bypass_mode": "always"}])]), env=env, origin=origin)
            self.assertFalse(r["ok"]); self._findings_once(r, "bypass actor(s)"); self.assertEqual(len(r["findings"]), 1)
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL, bypass=[{"actor_id": 5, "bypass_mode": "pull_request"}])]), env=env, origin=origin); self.assertTrue(r["ok"], r); self.assertEqual(r["branches"]["main"]["unverifiable"], [])
            # a protected branch the server does not have protects nothing; two branches, one reached
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL)], branches=("develop",)), env=env, origin=origin); self.assertFalse(r["ok"]); self._findings_once(r, "does not exist on the server"); self.assertEqual(len(r["findings"]), 1)
            repo3 = self._repo(tmp + "/two", checks=("governance-check", "lockstep"), branches=("main", "release"))
            r = scm.check(repo3, "ci", fetch=gh([self._rs(self.FULL, include=("refs/heads/main",))], branches=("main", "release")), env=env, origin=origin)
            self.assertFalse(r["ok"]); self.assertTrue(r["findings"] and all(f.startswith("`release`") for f in r["findings"]), r["findings"]); self.assertIn("on main, release", r["reason"])
            # the control points: push and static never ask the server; ci without a token is n/a with the checklist, never green — unless the runner has one and hides it
            for cp in ("push", "static"):
                r = scm.check(repo, cp, fetch=gh([self._rs(self.FULL)]), env=env, origin=origin); self.assertTrue(r["ok"]); self.assertEqual(r["status"], "n/a"); self.assertIn("cannot see the server", r["reason"]); self.assertEqual(r["checklist"], scm.CHECKLIST)
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL)]), env={}, origin=origin); self.assertEqual(r["status"], "n/a"); self.assertIn("no GITHUB_TOKEN / GH_TOKEN", r["reason"]); self.assertIn("checklist:", scm.render(r))
            r = scm.check(repo, "ci", fetch=gh([self._rs(self.FULL)]), env={"GITHUB_ACTIONS": "true"}, origin=origin); self.assertFalse(r["ok"]); self.assertEqual(r["status"], "RED"); self.assertIn("does not export it", r["reason"]); self.assertIn("GH_TOKEN", r["reason"])
            # the config must name the host origin points at
            r = scm.check(self._repo(tmp + "/gl", platform="GitLab"), "ci", fetch=gh(), env={"GITLAB_TOKEN": "t"}, origin=origin); self.assertFalse(r["ok"]); self.assertIn("origin points at github.com (GitHub)", r["reason"])
            # an API error is a fault, never a pass; a missing config block is RED; required false needs its reason; Other is the checklist
            def boom(url, headers, missing_ok=False): raise GateFault("the SCM API answered 500")
            with self.assertRaisesRegex(GateFault, "500"):
                scm.check(repo, "ci", fetch=boom, env=env, origin=origin)
            q = json.loads((repo / "config/quality.json").read_text()); q["scm"]["platform"] = "Other"; q["scm"]["required_checks"] = []; write(repo / "config/quality.json", json.dumps(q))
            r = scm.check(repo, "ci", fetch=boom, env=env, origin=origin); self.assertEqual(r["status"], "n/a"); self.assertIn("no adapter", r["reason"])
            for block, needle in (({"required": False}, "without a `reason`"),
                                  ({"platform": "Gitea"}, "not one of"),
                                  ({"platform": "GitHub", "required_checks": []}, "required_checks is empty"),
                                  ({"platform": "GitHub", "required_checks": ["governance-check"], "approvals": True}, "must be an integer"),
                                  ({"platform": "GitHub", "required_checks": ["governance-check"], "protected_branches": "main"}, "non-empty list of branch names")):
                q["scm"] = block; write(repo / "config/quality.json", json.dumps(q))
                r = scm.check(repo, "ci", fetch=boom, env=env, origin=origin); self.assertFalse(r["ok"], block); self.assertIn(needle, r["reason"])
            q["scm"] = {"required": False, "reason": "no server"}; write(repo / "config/quality.json", json.dumps(q))
            r = scm.check(repo, "ci"); self.assertTrue(r["ok"]); self.assertEqual(r["status"], "n/a"); self.assertFalse(r["required"])
            del q["scm"]; write(repo / "config/quality.json", json.dumps(q))
            r = scm.check(repo, "ci"); self.assertFalse(r["ok"]); self.assertIn("`scm` is missing", r["reason"])

    def test_gitlab_adapter(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp, platform="GitLab", approvals=1); env = {"GITLAB_TOKEN": "t"}; origin = "https://gitlab.com/g/p.git"
            def gl(protected, pipeline=True, rules=None):
                def fetch(url, headers, missing_ok=False):
                    if url.endswith("/projects/g%2Fp"): return {"only_allow_merge_if_pipeline_succeeds": pipeline}
                    if "/protected_branches/" in url:
                        if protected is None:
                            self.assertTrue(missing_ok); return None
                        return protected
                    if url.endswith("/approval_rules"):
                        if rules == "forbidden": raise GateFault("refused (403)")
                        return rules
                    raise AssertionError(url)
                return fetch
            # no one may push, force-push off, pipelines must succeed, one approval rule → green; a protected branch cannot be deleted
            r = scm.check(repo, "ci", fetch=gl({"push_access_levels": [{"access_level": 0}], "allow_force_push": False}, rules=[{"approvals_required": 1}]), env=env, origin=origin)
            self.assertTrue(r["ok"], r); self.assertTrue(r["branches"]["main"]["deletion_blocked"]); self.assertEqual(r["branches"]["main"]["checks"], ["pipeline must succeed"])
            # maintainers may push, force-push on, no pipeline rule, no approval rule → every setting named once
            r = scm.check(repo, "ci", fetch=gl({"push_access_levels": [{"access_level": 40}], "allow_force_push": True}, pipeline=False, rules=[]), env=env, origin=origin)
            self.assertFalse(r["ok"]); self._findings_once(r, "pull request is not required", "no pipeline / build is required", "force-push forbidden is not set", "0 approval(s) required, the project decided 1"); self.assertEqual(len(r["findings"]), 4)
            # the branch is not protected at all (404 = an answer here): pull request, force-push AND deletion red — never "unverifiable"
            r = scm.check(repo, "ci", fetch=gl(None, rules=[{"approvals_required": 1}]), env=env, origin=origin)
            self.assertFalse(r["ok"]); self._findings_once(r, *self.NEEDLES); self.assertEqual(r["unverifiable"], [])
            # approval rules refused (Free tier): not exposed, listed — never a fault, never red
            r = scm.check(repo, "ci", fetch=gl({"push_access_levels": [{"access_level": 0}], "allow_force_push": False}, rules="forbidden"), env=env, origin=origin)
            self.assertTrue(r["ok"], r); self.assertEqual(len(r["unverifiable"]), 1); self.assertIn("Premium", r["unverifiable"][0]); self.assertIn("not exposed by the API", r["reason"])

    def test_bitbucket_adapter(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp, platform="Bitbucket", approvals=1); env = {"BITBUCKET_TOKEN": "u:p"}; origin = "git@bitbucket.org:ws/slug.git"
            def bb(values, model=None, pages=1):
                chunks = [values[i::pages] for i in range(pages)] if pages > 1 else [values]
                def fetch(url, headers, missing_ok=False):
                    if url.endswith("/repositories/ws/slug"): return {"slug": "slug"}
                    if url.endswith("/branching-model"):
                        self.assertTrue(missing_ok); return model
                    if "/branch-restrictions" in url:
                        n = int(url.split("page=")[1]) if "page=" in url else 0
                        page = {"values": chunks[n]}
                        if n + 1 < len(chunks): page["next"] = f"{url.split('&page=')[0]}&page={n + 1}"
                        return page
                    raise AssertionError(url)
                return fetch
            full = [{"kind": "push", "branch_match_kind": "glob", "pattern": "main", "users": [], "groups": []}, {"kind": "force", "branch_match_kind": "glob", "pattern": "main"}, {"kind": "delete", "branch_match_kind": "glob", "pattern": "main"},
                    {"kind": "require_passing_builds_to_merge", "branch_match_kind": "glob", "pattern": "main", "value": 1}, {"kind": "require_approvals_to_merge", "branch_match_kind": "glob", "pattern": "main", "value": 1},
                    {"kind": "enforce_merge_checks", "branch_match_kind": "glob", "pattern": "main"}]
            r = scm.check(repo, "ci", fetch=bb(full), env=env, origin=origin); self.assertTrue(r["ok"], r); self.assertEqual(r["branches"]["main"]["checks"], ["1 passing build(s)"]); self.assertEqual(r["branches"]["main"]["approvals"], 1)
            r = scm.check(repo, "ci", fetch=bb(full, pages=3), env=env, origin=origin); self.assertTrue(r["ok"], "the restrictions are paginated — every page is read")
            # a glob pattern Bitbucket honours; the branching-model kind resolved through the model (production = main, development = develop)
            r = scm.check(repo, "ci", fetch=bb([{**v, "pattern": "ma*"} for v in full]), env=env, origin=origin); self.assertTrue(r["ok"], r)
            model = {"production": {"branch": {"name": "main"}}, "development": {"branch": {"name": "develop"}}}
            bm = [{**v, "branch_match_kind": "branching_model", "branch_type": "production", "pattern": None} for v in full]
            r = scm.check(repo, "ci", fetch=bb(bm, model=model), env=env, origin=origin); self.assertTrue(r["ok"], r)
            r = scm.check(repo, "ci", fetch=bb([{**v, "branch_type": "development"} for v in bm], model=model), env=env, origin=origin); self.assertFalse(r["ok"], "restrictions on the development branch protect nothing on main")
            # without enforce_merge_checks the builds and approvals are advisory: a finding of their own, not a silent green
            r = scm.check(repo, "ci", fetch=bb(full[:-1]), env=env, origin=origin); self.assertFalse(r["ok"]); self._findings_once(r, "merge checks are advisory"); self.assertEqual(len(r["findings"]), 1); self.assertIn("approvals (merge checks not enforced)", " ".join(r["unverifiable"]))
            # nothing restricted: every setting named exactly once
            r = scm.check(repo, "ci", fetch=bb([]), env=env, origin=origin); self.assertFalse(r["ok"]); self._findings_once(r, *self.NEEDLES, "no pipeline / build is required"); self.assertEqual(len(r["findings"]), 4)

    def test_azure_adapter(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp, platform="Azure DevOps", approvals=1); env = {"AZURE_DEVOPS_TOKEN": "pat"}; origin = "https://dev.azure.com/org/Proj/_git/repo"
            BUILD, REVIEWERS = "0609b952-1397-4640-95ec-e00a01b2c241", "fa4e907d-c16b-4a4c-9dfa-4906e5d171dd"
            def az(policies, default="refs/heads/main"):
                def fetch(url, headers, missing_ok=False):
                    if "/_apis/git/repositories/repo" in url: return {"id": "RID", "defaultBranch": default}
                    if "/_apis/policy/configurations" in url: return {"value": policies}
                    raise AssertionError(url)
                return fetch
            def pol(kind, scope, **kw):
                base = {"isEnabled": True, "isBlocking": True, "isDeleted": False}
                if kind == "build":
                    return {**base, "type": {"id": BUILD, "displayName": "Build"}, "settings": {"displayName": "governance-check", "scope": scope}, **kw}
                return {**base, "type": {"id": REVIEWERS, "displayName": "Minimum number of reviewers"}, "settings": {"minimumApproverCount": 1, "scope": scope}, **kw}
            exact = [{"repositoryId": "RID", "matchKind": "Exact", "refName": "refs/heads/main"}]
            r = scm.check(repo, "ci", fetch=az([pol("build", exact), pol("reviewers", exact)]), env=env, origin=origin)
            self.assertTrue(r["ok"], r); self.assertEqual(len(r["unverifiable"]), 2); self.assertIn("not exposed by the API", r["reason"]); self.assertEqual(r["branches"]["main"]["checks"], ["governance-check"])
            # the scope shapes Azure has: Prefix, DefaultBranch, a null repositoryId (project-wide); another repository's policy is not this one's
            for scope in ([{"repositoryId": "RID", "matchKind": "Prefix", "refName": "refs/heads/ma"}], [{"repositoryId": None, "matchKind": "DefaultBranch", "refName": None}], [{"repositoryId": None, "matchKind": "Exact", "refName": "refs/heads/main"}]):
                r = scm.check(repo, "ci", fetch=az([pol("build", scope), pol("reviewers", scope)]), env=env, origin=origin); self.assertTrue(r["ok"], (scope, r))
            other = [{"repositoryId": "OTHER", "matchKind": "Exact", "refName": "refs/heads/main"}]
            r = scm.check(repo, "ci", fetch=az([pol("build", other), pol("reviewers", other)]), env=env, origin=origin); self.assertFalse(r["ok"], "another repository's policy protects nothing here")
            r = scm.check(repo, "ci", fetch=az([pol("build", exact), pol("reviewers", exact)], default="refs/heads/develop"), env=env, origin=origin); self.assertTrue(r["ok"], "Exact scope does not depend on the default branch")
            r = scm.check(repo, "ci", fetch=az([pol("build", [{"repositoryId": None, "matchKind": "DefaultBranch"}])], default="refs/heads/develop"), env=env, origin=origin); self.assertFalse(r["ok"], "DefaultBranch scope on a server whose default is develop")
            # a non-blocking, a disabled or a deleted policy defends nothing; a displayName-only type still resolves
            for kw in ({"isBlocking": False}, {"isEnabled": False}, {"isDeleted": True}):
                r = scm.check(repo, "ci", fetch=az([pol("build", exact, **kw), pol("reviewers", exact, **kw)]), env=env, origin=origin); self.assertFalse(r["ok"], kw)
            legacy = [{"isEnabled": True, "isBlocking": True, "type": {"displayName": "Build"}, "settings": {"displayName": "governance-check", "scope": [{"refName": "refs/heads/main"}]}},
                      {"isEnabled": True, "isBlocking": True, "type": {"displayName": "Minimum number of reviewers"}, "settings": {"minimumApproverCount": 1, "scope": [{"refName": "refs/heads/main"}]}}]
            r = scm.check(repo, "ci", fetch=az(legacy), env=env, origin=origin); self.assertTrue(r["ok"], r)
            r = scm.check(repo, "ci", fetch=az([]), env=env, origin=origin); self.assertFalse(r["ok"]); self._findings_once(r, "pull request is not required", "not enforced by the server: governance-check"); self.assertEqual(len(r["findings"]), 2, "force-push and deletion are permissions — unverifiable, never red")

    def test_scm_protection_is_a_light_member_run_at_ci(self):
        """The member and its runner: the control point token reaches the reader (drop it and CI would say 'cannot see the server' forever)."""
        from unittest import mock
        self.assertIn("scm-protection", {m["member"] for m in profile.owed("light")})
        runner = next(m[4] for m in profile.MEMBERS if m[0] == "scm-protection")
        self.assertEqual(profile._cmd(Path("."), runner, "origin/main", "b", "ci")[-2:], ["--control-point", "ci"])
        with tempfile.TemporaryDirectory() as tmp:
            repo = Profile()._repo(tmp, mode="production")
            q = json.loads((repo / "config/quality.json").read_text())
            q["scm"] = {"platform": "GitHub", "protected_branches": ["main"], "required_checks": ["governance-check"], "approvals": 0}
            write(repo / "config/quality.json", json.dumps(q))
            subprocess.run(["git", "-C", str(repo), "remote", "add", "origin", "git@github.com:acme/app.git"], check=True)
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "feature/F-002-x"], check=True)
            with mock.patch.dict(os.environ, {"GITHUB_ACTIONS": "true", "GH_TOKEN": "", "GITHUB_TOKEN": ""}):
                rep = profile.run(repo, base="origin/main", control_point="ci", only=["scm-protection"])
                by = {r["member"]: r for r in rep["results"]}
                self.assertEqual(by["scm-protection"]["status"], "RED", by); self.assertIn("does not export it", by["scm-protection"]["tail"], "at ci the reader ran at ci: the runner's hidden token is the finding — never 'cannot see the server'")
                rep = profile.run(repo, base="origin/main", control_point="push", only=["scm-protection"])
                by = {r["member"]: r for r in rep["results"]}
                self.assertEqual(by["scm-protection"]["status"], "n/a"); self.assertIn("cannot see the server", by["scm-protection"]["tail"])


