            subprocess.run(["git", "-C", str(repo), "update-ref", "refs/remotes/origin/main", "HEAD"], check=True)
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "feature/F-001-x"], check=True)
            write(repo / "src/new.py", "1\n"); subprocess.run(["git", "-C", str(repo), "add", "src/new.py"], check=True)   # only this file: the fixture edits above stay unstaged
            subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "one"], check=True)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "surface", "--base", "origin/main", "--json"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0); self.assertEqual((json.loads(r.stdout)["files"], json.loads(r.stdout)["ok"]), (1, True))
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "certify", "--subject", "tree", "--paths", "src/**", "--json", "--branch", "nonsense"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0, "a tree certification needs no base — never classifies a branch")
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "--detach"], check=True)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "diff-base"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 2); self.assertIn("detached HEAD", r.stderr)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "surface", "--base", "origin/main"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0, "the CI shape — explicit base on a detached checkout — keeps working")
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "certify", "--subject", "tree", "--paths", "src/**", "--json"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0, "QA certifies a tree on a tag / detached checkout")
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "profile"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0); self.assertIn("profile: full", r.stdout); self.assertIn("strictest mode", r.stdout, "no manifest → production, said")
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "one-definition"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0)
            write(repo / "scripts/hooks/pre-push", "PROTECTED_BRANCHES=main\n")
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "one-definition"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1); self.assertIn("scripts/hooks/pre-push:1", r.stdout)
            (repo / "scripts/hooks/pre-push").unlink()
            subprocess.run(["git", "-C", str(repo), "checkout", "-q", "--detach"], check=True)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "profile", "--run", "--control-point", "ci", "--base", "origin/main", "--branch", "feature/F-001-x", "--json"], capture_output=True, text=True, env=env)
            rep = json.loads(r.stdout)
            self.assertEqual((rep["base"], rep["profile"]), ("origin/main", "full"), "the CI shape: explicit base + head ref on a detached checkout")
            self.assertTrue(rep["results"], "members ran"); self.assertEqual(r.returncode, 1 if rep["verdict"] == "RED" else 2 if rep["verdict"] == "FAULT" else 0)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "runtime-surface", "--changed", "--base", "origin/main"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0, "no surface declared in this fixture → touched (fail-closed towards deploying)"); self.assertIn("no runtime surface declared", r.stdout)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "runtime-surface"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1); self.assertIn("is empty", r.stdout)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "runtime-surface", "--json"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1); self.assertIn("is empty", json.loads(r.stdout)["findings"][0]["reason"])
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "runtime-surface", "--changed", "--base", "nope/ref"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 2, "an unresolvable base cannot be judged — the workflows tag to be safe"); self.assertIn("gate:", r.stderr)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "plan", "--path", "src/app.py", "--branch", "fix/x"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 2, "no planning block in this fixture: a fault, said"); self.assertIn("`planning` is missing", r.stderr)
            q = json.loads((repo / "config/quality.json").read_text()); q["planning"] = Planning.PLAN; write(repo / "config/quality.json", json.dumps(q))
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "plan", "--path", "src/app.py", "--branch", "fix/x"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1); self.assertIn("plan: BLOCKED", r.stdout); self.assertIn("Resolution", r.stdout)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "plan", "--path", "docs/x.md", "--branch", "fix/x"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "plan", "--record", "--hook-json", "--branch", "fix/x"], input=json.dumps({"hook_event_name": "PostToolUse", "tool_name": "Edit"}), capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 2, "a forged approval is refused"); self.assertIn("only from the harness", r.stderr)
            write(repo / "t.jsonl", '{"name":"ExitPlanMode","id":"toolu_1"}\n')
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "plan", "--record", "--hook-json", "--branch", "fix/x"], input=json.dumps({"hook_event_name": "PostToolUse", "tool_name": "ExitPlanMode", "session_id": "s", "transcript_path": str(repo / "t.jsonl"), "tool_use_id": "toolu_1"}), capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0, r.stderr); self.assertIn("approval recorded for fix/x", r.stdout)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "plan", "--enter", "--branch", "feature/F-001-x"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1); self.assertIn("second stage", r.stdout)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "plan", "--enter", "--branch", "fix/x"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "agents"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 2, "no agents policy in this fixture: a fault, said"); self.assertIn("agents.md is missing", r.stderr)
            write(repo / ".claude/rules/agents.md", RULE_AGENTS); write(repo / ".claude/agents/factory-dev-backend.md", agent_def("factory-dev-backend", "worker", "Read, Edit, Write, Bash"))
            q = json.loads((repo / "config/quality.json").read_text()); q["agents"] = {"families": {"writer": "sonnet", "critic": "sonnet"}}; write(repo / "config/quality.json", json.dumps(q))
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "agents"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1); self.assertIn("same alias", r.stdout)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "agents", "--resolve", "--class", "worker", "--files", "1", "--lines", "1", "--json"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0); self.assertEqual(json.loads(r.stdout)["effort"], "low")
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "agents", "--fallback", "--class", "worker", "--family", "writer"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1); self.assertIn("never degrades", r.stdout)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "agents", "--check-return", "--class", "worker"], input="did x", capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1); self.assertIn("REFUSED", r.stdout)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "plan", "--path", "src/app.py", "--branch", "fix/x"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "plan", "--status", "--branch", "chore/z"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 0, "the advisory never fails the prompt"); self.assertIn("will be BLOCKED", r.stdout)


